(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0027.js"] = [{"id":"poem-b0bbdb184b25e9466019c7de","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我东人尽日，常怀忧虑。","只愁二亲在途路里，孝思情意真个感神祗。","(合前)(丑唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5203","tags":[]},{"id":"poem-b0c17bc5","title":"临江仙·滚滚长江东逝水","author":"杨慎","dynasty":"明","verses":["滚滚长江东逝水，浪花淘尽英雄。","是非成败转头空。","青山依旧在，几度夕阳红。","白发渔樵江渚上，惯看秋月春风。","一壶浊酒喜相逢。","古今多少事，都付笑谈中。"],"enabled":true,"collection":"历代名篇","source":"杨慎《廿一史弹词》第三段《说秦汉》开场词。","tags":["咏史"]},{"id":"poem-b0c4951344a5658ad96408f5","title":"七夕卧病","author":"郑愿","dynasty":"唐","verses":["玉露三秋早，反河七夕初。","不应须卧疾，为曝腹中书。","（〖1〗郑愿，《新唐书·宰相世系表》载为郑氏南祖房清河令文睿子，无仕历。","《郎官石柱题名》其名两见，司勋员外郎在卢象后，李嘉祐前，金部郎中在裴眺、郑楚客间，以诸人时代推，应为天宝、大历间人。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e9b368fb-2140-4a90-b126-0175ed4c43d6","tags":[]},{"id":"poem-b0c7933522be2c32902fb3ab","title":"古钗叹","author":"张籍","dynasty":"唐","verses":["古钗堕井无颜色，百尺泥中今复得。","凤凰宛转有古仪，欲为首饰不称时。","女伴传看不知主，罗袖拂拭生光辉。","兰膏已尽股半折，雕文刻样无年月。","虽离井底入匣中，不用还与坠时同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a5466d66-fe78-40d7-a3e6-3bbb2cf58405","tags":[]},{"id":"poem-b0d0b777221302100bf0ce82","title":"雪","author":"释居简","dynasty":"宋","verses":["集霰夜才分，缤霏晓更零。","未乘风洒洒，先挟雨冥冥。","窗失三更黑，山无一寸青。","有船非剡櫂，谁去扣吟扃。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6036ac20-e1b3-4025-af2c-6cfdccd554fb","tags":[]},{"id":"poem-b0d205bb398a64662b0dfb62","title":"点绛唇·新月娟娟","author":"苏过","dynasty":"宋","verses":["新月娟娟，夜寒江静山衔斗。","起来搔首。","梅影横窗瘦。","好个霜天，闲却传杯手。","君知否。","乱鸦啼后。","归兴浓如酒。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-262","tags":["宋词三百首"]},{"id":"poem-b0d39553a90bf3d34fd9f0f0","title":"朝阳洞","author":"吕愿中","dynasty":"宋","verses":["半世观山鬓已皤，欲求钓艇老渔蓑。","杖藜又过烟霞洞，闻说当年烂斧柯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-5681506f-aa0c-4afc-8a41-53dda5cfd29f","tags":[]},{"id":"poem-b0d4dd348737b9e187666d28","title":"访袁拾遗不遇","author":"孟浩然","dynasty":"唐","verses":["洛阳访才子，江岭作流人。","闻说梅花早，何如此地春。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-訪袁拾遺不遇","tags":[]},{"id":"poem-b0e6c340f91e0c5fba0298e8","title":"移梅竹谢彰教寺事","author":"释居简","dynasty":"宋","verses":["苍玉根连白玉条，湿云冉冉碧萧萧。","花含鼎实宜先发，节笑心空贵后凋。","友此双清同日种，听它六出几时飘。","不如杨柳江边树，惠浅恩疎怨不消。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-239aa1d8-a5a3-4119-b657-b2e93bad6bde","tags":[]},{"id":"poem-b0e826d339b259ab32be9537","title":"夜游宫·一带垂杨蘸水","author":"方千里","dynasty":"宋","verses":["一带垂杨蘸水。","映芳草、萋萋千里。","跋马回堤少年子。","拥青娥，向红楼，南酒市。","拼饮莺花底。","恣欢笑、粉融香坠。","不趁临分醉中起。","但依稀，写柔情，留蜀纸。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-542","tags":[]},{"id":"poem-b0ed455d8487f6800da4aef8","title":"拟寒山 四","author":"泰钦","dynasty":"唐","verses":["闲步游南陌，唯便野兴多。","傍花看蝶舞，近柳听莺歌。","稚子捞溪莱，山翁携蕨萝。","问渠何处住，回首指前坡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-200995ae-d00d-4114-be20-37ea235cea03","tags":[]},{"id":"poem-b0eeaee231d968cc29bed082","title":"客夜与故人偶集","author":"戴叔伦","dynasty":"唐","verses":["天秋月又满，城阙夜千重。","还作江南会，翻疑梦里逢。","风枝惊暗鹊，露草覆寒蛩。","羁旅长堪醉，相留畏晓钟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-94ae3e7e-eb5d-414c-bfd6-124f50687ce5","tags":["唐诗三百首","友情","写景","秋天","五言律诗","相聚"]},{"id":"poem-b0efad810e739f8177d5135d","title":"菩萨蛮·人人尽说江南好","author":"韦庄","dynasty":"五代","verses":["人人尽说江南好，游人只合江南老。","春水碧于天，画船听雨眠。","垆边人似月，皓腕凝双雪。","未老莫还乡，还乡须断肠。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-34","tags":[]},{"id":"poem-b0f399520e4e98bb3e481e60","title":"梅","author":"吕从庆","dynasty":"唐","verses":["最爱横溪曲，横流一树梅。","藏根惟爱石，落瓣不沾埃。","腊里孤清节，春间创辟材。","调羹还有藉，青子百千枚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-a5f9605a-ec79-437d-81d9-9f842432800d","tags":[]},{"id":"poem-b103fe84fe6c9332e3807d63","title":"叹庭前甘菊花","author":"杜甫","dynasty":"唐","verses":["檐前甘菊移时晚，青蘂重阳不堪摘。","明日萧条醉尽醒，残花烂熳开何益。","篱边野外多众芳，采撷细琐升中堂。","念兹空长大枝叶，结根失所缠风霜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a0da6bc2-f1d1-468f-885f-4b515398106b","tags":["同情","菊花","抒怀","花","写花","愤懑"]},{"id":"poem-b10402fa6c4db6c16e271262","title":"鹧鸪天·报答风光思更新","author":"洪适","dynasty":"宋","verses":["报答风光思更新。","安排好语续阳春。","罗胸玉藻英华别，信手银钩点画匀。","歌妙曲，想光尘。","相望尺五叹参辰。","曲终强对红颜笑，欠我高谈惊座人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-668","tags":[]},{"id":"poem-b104ba1e922af0f444ef71e0","title":"赠妙胜主人","author":"陈造","dynasty":"宋","verses":["舆台却略车不前，寒风皴肌冰在袖。","还家大胜去家时，景物顿回春气候。","宿云坏裂无几留，满放羲轮碾晴昼。","卧石荦确犹润湿，短篱檀栾挺疎瘦。","是处麦畦间青壤，谁家柳阴围碧溜。","前山竞献晓髻浓，后海全收纹縠皱。","妖桃艳杏各趺萼，近树遥林错文绣。","池鱼酣煖泳清浅，山鸟何知语幽茂。","搜诗忽忘路远迩，啅鹊不离车前后。","闲身胜践多龃龉，缓驾幽寻容宿留。","转从净宇寄倦憩，得访老禅闲话旧。","拂除尘壁诗刻在，俛仰岁华春事又。","开单一饭吾易饱，袖手千倡渠无陋。","戴星摩抚防务废，挽袂留连惭意厚。","出处殊科要酬应，气味相投真邂逅。","吾归自竟武城歌，放师道价诸山右。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a4cc0af8-5a99-4d80-acdb-23369849d276","tags":[]},{"id":"poem-b106e5b648e5f2545ecb926a","title":"葛覃","author":"佚名","dynasty":"先秦","verses":["葛之覃兮，施于中谷，维叶萋萋。黄鸟于飞，集于灌木，其鸣喈喈。","葛之覃兮，施于中谷，维叶莫莫。是刈是濩，为𫄨为绤，服之无斁。","言告师氏，言告言归。薄污我私，薄浣我衣。害浣害否，归宁父母。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-1","tags":[]},{"id":"poem-b10cc45e537431dce9d35e91","title":"纸被","author":"徐夤","dynasty":"唐","verses":["文采鸳鸯罢合欢，细柔轻缀好鱼牋。","一床明月盖归梦，数尺白云笼冷眠。","披对劲风温胜酒，拥听寒风暖于绵。","赤眉豪客见皆笑，却问儒生直几钱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-341affc4-7db1-4ec9-ac5f-06aceca64739","tags":[]},{"id":"poem-b111c7624a65a7a9d8ae157a","title":"送知全禅师南游","author":"刘得仁","dynasty":"唐","verses":["师誉振京城，谈空万乘听。","北行山已雪，南去木犹青。","夜岳禅销月，秋潭汲动星。","回期不可定，孤鹤在高冥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4f3306e9-a602-49b5-8183-c04e89396d3d","tags":[]},{"id":"poem-b1171a51d0728e1003eb39ef","title":"题江陵崔兵曹林亭","author":"张祜","dynasty":"唐","verses":["小隐蜀江边，重峦尽一川。","山形分断岸，水势尽平田。","嫩碧生栏浅，轻红落砌蔫。","短桥扶竹过，欹路把藤缘。","南巷纤埃隔，东郊远思延。","月庭潜润石，风渚自移舡。","滴露蒲光冷，摇波柳翠鲜。","关心每来胜，幸尔必相然。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3ae06bee-e8ad-4a7d-abbd-f22b890d2f4b","tags":[]},{"id":"poem-b11780a118be77283d328f39","title":"清平调 二","author":"李白","dynasty":"唐","verses":["一枝红艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-73dadc56-88ff-4f11-9ff5-da0e0adf533c","tags":["女子","近代曲辞","唐诗三百首","乐府"]},{"id":"poem-b11a54d1c6e9f3f7d1ca3326","title":"长恨歌","author":"白居易","dynasty":"唐","verses":["汉皇重色思倾国，御宇多年求不得。","杨家有女初长成，养在深闺人未识。","天生丽质难自弃，一朝选在君王侧。","回眸一笑百媚生，六宫粉黛无颜色。","春寒赐浴华清池，温泉水滑洗凝脂。","侍儿扶起娇无力，始是新承恩泽时。","云鬓花颜金步摇，芙蓉帐暖度春宵。","春宵苦短日高起，从此君王不早朝。","承欢侍宴无闲暇，春从春游夜专夜。","后宫佳丽三千人，三千宠爱在一身。","金屋妆成娇侍夜，玉楼宴罢醉和春。","姊妹弟兄皆列土，可怜光彩生门户。","遂令天下父母心，不重生男重生女。","骊宫高处入青云，仙乐风飘处处闻。","缓歌慢舞凝丝竹，尽日君王看不足。","渔阳鞞鼓动地来，惊破霓裳羽衣曲。","九重城阙烟尘生，千乘万骑西南行。","翠华摇摇行复止，西出都门百余里。","六军不发无奈何，宛转蛾眉马前死。","花钿委地无人收，翠翘金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风萧索，云栈萦纡登劒阁。","峨嵋山下少人行，旌旗无光日色薄。","蜀江水碧蜀山青，圣主朝朝暮暮情。","行宫见月伤心色，夜雨闻铃肠断声。","天旋日转回龙驭，到此踌躇不能去。","马嵬坡下泥土中，不见玉颜空死处。","君臣相顾尽沾衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐叶落时。","西宫南苑多秋草，宫叶满阶红不埽。","棃园弟子白发新，椒房阿监青娥老。","夕殿萤飞思悄然，孤灯挑尽未成眠。","迟迟钟鼓初长夜，耿耿星河欲曙天。","鸳鸯瓦冷霜华重，翡翠衾寒谁与共。","悠悠生死别经年，魂魄不曾来入梦。","临邛道士鸿都客，能以精诚致魂魄。","为感君王展转思，遂教方士殷勤觅。","排空驭气奔如电，升天入地求之徧。","上穷碧落下黄泉，两处茫茫皆不见。","忽闻海上有仙山，山在虚无缥缈间。","楼阁玲珑五云起，其中绰约多仙子。","中有一人字太真，雪肤花貌参差是。","金阙西厢叩玉扃，转教小玉报双成。","闻道汉家天子使，九华帐里梦魂惊。","揽衣推枕起裴回，珠箔银屏逦迤开。","云鬓半偏新睡觉，花冠不整下堂来。","风吹仙袂飘飖举，犹似霓裳羽衣舞。","玉容寂莫泪阑干，棃花一枝春带雨。","含情凝睇谢君王，一别音容两渺茫。","昭阳殿里恩爱绝，蓬莱宫中日月长。","回头下望人寰处，不见长安见尘雾。","唯将旧物表深情，钿合金钗寄将去。","钗留一股合一扇，钗擘黄金合分钿。","但教心似金钿坚，天上人间会相见。","临别殷勤重寄词，词中有誓两心知。","七月七日长生殿，夜半无人私语时。","在天愿作比翼鸟，在地愿为连理枝。","天长地久有时尽，此恨緜緜无绝期。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0a0f9231-d88c-4f81-b941-83b67a736194","tags":["唐诗三百首","峨眉山","叙事","写人","爱情","七言古诗","长诗","讽喻"]},{"id":"poem-b11dee4e3cfc8255c8f0386c","title":"西江月·小舫半帘山色","author":"高观国","dynasty":"宋","verses":["小舫半帘山色，断桥两岸秋阴。","芙蓉消息已愁深。","红染云机翠锦。","几度烟波共酌，半生风月关心。","飞来鸥鹭是知音。","一笑歌边醉醒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-393","tags":[]},{"id":"poem-b120b5c162ebe9cfe45725af","title":"陟岵","author":"佚名","dynasty":"先秦","verses":["陟彼岵兮，瞻望父兮。父曰：嗟！予子行役，夙夜无已。上慎旃哉，犹来！无止！","陟彼屺兮，瞻望母兮。母曰：嗟！予季行役，夙夜无寐。上慎旃哉，犹来！无弃！","陟彼冈兮，瞻望兄兮。兄曰：嗟！予弟行役，夙夜必偕。上慎旃哉，犹来！无死！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-109","tags":[]},{"id":"poem-b12de0dcf9e6903746322fe3","title":"三月晦日送春","author":"贾岛","dynasty":"唐","verses":["三月正当三十日，风光别我苦吟身。","共君今夜不须睡，未到晓钟犹是春。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-三月晦日送春","tags":[]},{"id":"poem-b12ed87d03956b07e93c4925","title":"游岳寻梅不获和元晦韵","author":"张栻","dynasty":"宋","verses":["眼看飞雪洒千林，更著寒溪水浅深。","应有梅花连夜发，却烦诗句写愁襟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-26713ab9-aac3-44d6-8542-30868faa371c","tags":[]},{"id":"poem-b12fc5cf250eccfee60bf7ac","title":"帝京篇十首 六","author":"太宗皇帝","dynasty":"唐","verses":["飞盖去芳园，兰桡游翠渚。","萍间日彩乱，荷处香风举。","桂楫满中川，弦歌振长屿。","岂必汾河曲，方为欢宴所。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-90bcc00c-bcdb-424e-947b-cf108c47416b","tags":[]},{"id":"poem-b131a0a4b97a1dba8675f234","title":"读杜工部集二首 二","author":"贯休","dynasty":"唐","verses":["甫也道亦丧，孤身出蜀城。","彩毫终不撅，白云更能轻。","命薄相如命，名齐李白名。","不知耒阳令，何以葬先生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-8e7c374d-32dc-449d-9f57-ee519658a459","tags":[]},{"id":"poem-b1326eb726aadbda34317dcc","title":"景阳台怀古","author":"徐铉","dynasty":"宋","verses":["后主亡家不悔，江南异代长春。","今日景阳台上，闲人何用伤神。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c59df47f-d3ea-4feb-9583-921123d86f96","tags":[]},{"id":"poem-b13a6d198284015566f3a13c","title":"入直召对选德殿赐茶而退","author":"周必大","dynasty":"宋","verses":["绿槐夹道集昏鸦，敕使传宣坐赐茶。","归到玉堂清不寐，月钩初上紫薇花。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-入直召對選德殿賜茶而退","tags":[]},{"id":"poem-b13bb3daba2b9f6ade6d2580","title":"朝中措·萧萧芦叶暮寒生","author":"张抡","dynasty":"宋","verses":["萧萧芦叶暮寒生。","雪厌冻云平。","密洒一篷烟火，惊鸿飞起沙汀。","收纶罢钓，空江有浪，短棹无声。","便是天然图画，何须妙手丹青。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-951","tags":[]},{"id":"poem-b14c0c6ac0f6a385b2ec038a","title":"·","author":"王昌龄","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c7dae33e-003f-4f7e-9f78-2c8c7d7d7033","tags":[]},{"id":"poem-b14ceefb2b65c5b99f420b23","title":"硕人","author":"佚名","dynasty":"先秦","verses":["硕人其颀，衣锦褧衣。齐侯之子，卫侯之妻。东宫之妹，邢侯之姨，谭公维私。","手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮。","硕人敖敖，说于农郊。四牡有骄，朱幩镳镳。翟茀以朝。大夫夙退，无使君劳。","河水洋洋，北流活活。施罛濊濊，鳣鲔发发。葭菼揭揭，庶姜孽孽，庶士有朅。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-56","tags":[]},{"id":"poem-b1534179be42e963f8cb6e6a","title":"奉应颜尚书真卿观玄真子置酒张乐舞破阵画洞庭三山歌","author":"皎然","dynasty":"唐","verses":["道流迹异人共惊，寄向画中观道情。","如何万象自心出，而心澹然无所营。","手援毫，足蹈节，披缣洒墨称丽绝。","石文乱点急管催，云态徐挥慢歌发。","乐纵酒酣狂更好，攒峰若雨纵横埽。","尺波澶漫意无涯，片岭崚嶒势将倒。","盻睐方知造境难，象忘神遇非笔端。","昨日幽奇湖上见，今朝舒卷手中看。","兴余轻拂远天色，曾向峰东海边识。","秋空暮景飒飒容，翻疑是真画不得。","颜公素高山水意，常恨三山不可至。","赏君狂画忘远游，不出轩墀坐苍翠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-61be085b-5ba1-4a7c-bfe8-9a37c6d608b5","tags":["洞庭湖"]},{"id":"poem-b153e9d741ac1c9d4166dc01","title":"赠阙下裴舍人","author":"钱起","dynasty":"唐","verses":["二月黄莺飞上林，春城紫禁晓阴阴。","长乐钟声花外尽，龙池柳色雨中深。","阳和不散穷途恨，霄汉长怀捧日新。","献赋十年犹未遇，羞将白发对华簪。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-42f17f00-bbc1-4b5b-82c1-3e9e012725ba","tags":["唐诗三百首","援引","七言律诗"]},{"id":"poem-b16a17bfc071d43ac639949e","title":"逍遥台","author":"陈岩","dynasty":"宋","verses":["拂面溪风洒洒清，轻衫短帽御风行。","逍遥自是天游乐，不结沙鸥水石盟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e3c2df8e-2d9c-4ce5-8b57-e0c9047a0a7f","tags":[]},{"id":"poem-b16b342572f0ed675e866ade","title":"兵要望江南 《周易》占候第二十六（三十七首） 六","author":"易静","dynasty":"唐","verses":["彼与我，子鬼取为先。","子孙旺相吾军胜，鬼爻囚死彼（辛本、川本作「复」）遭愆，反此亦如然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-608132b3-d5c4-45b3-9699-c79941ea4ea9","tags":[]},{"id":"poem-b16f77df2f6e967dd5c3ed85","title":"残丝曲","author":"卢郢","dynasty":"宋","verses":["春风骀荡吹人衣，残丝罥花曳空飞。","闲愁十丈断不得，雄蜂雌蝶相因依。","高楼夹路凌云起，琐窗鸾柱弹流水。","鶑声啼老杨柳烟，香梦蒙蒙隔千里。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0f1302af-b7c7-4c62-a566-7e8c7a23dcde","tags":[]},{"id":"poem-b17b1bc0f15d38cd8c8e3765","title":"偈颂（幷序○序为南岳齐己撰） 二十七","author":"居遁","dynasty":"唐","verses":["缘觉（《景德传灯录》卷二九作「菩萨」）声闻未尽空，人天来往访真宗。","争如（《景德传灯录》作「知」）佛是无疑士，端坐无心祇么通。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5728316f-ee67-4171-835c-01e2e12026a0","tags":["衡山"]},{"id":"poem-b18b3d3b11385993f2283905","title":"对雨闲吟呈吏部侍郎","author":"李昉","dynasty":"宋","verses":["羃羃浓云势未收，森森凉气忽如秋。","密笼芳树飘何急，高卷疏帘看不休。","咫尺莫闻人对语，逡巡已见水平流。","此时遥忆诸君子，堪命棋枰与酒瓯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b849e3b7-e257-4136-b667-632356ab70af","tags":[]},{"id":"poem-b18b899325df92300b2ba61f","title":"临洞庭","author":"孟浩然","dynasty":"唐","verses":["八月湖水平，涵虚混太清。","气蒸云梦泽，波撼岳阳城。","欲济无舟楫，端居耻圣明。","坐观垂钓者，徒有羡鱼情。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-臨洞庭","tags":[]},{"id":"poem-b18c5210c6bf09b94d7cc518","title":"和叔崇清明后四绝  其二","author":"王柏","dynasty":"宋","verses":["安期老子肯过从，每恨清尊不肯空。","好句忽来今日雨，高情终是古人风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-74b45c6b-3f22-4b7e-b4fc-5a735e363a7b","tags":[]},{"id":"poem-b19bda23e472b4f3797d922c","title":"尾声","author":"施惠《幽闺记》","dynasty":"元","verses":["埋名避祸挨时运，满望取皇家赦恩。","罪大弥天，其时许自新。","(生)古语积善逢善，(小生)常言知恩报恩。","(合)此去愿逢吉地，前行莫撞凶门。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2893","tags":[]},{"id":"poem-b1a44d617e96cd0a388bdae4","title":"和上巳连寒食有怀京洛","author":"孙逖","dynasty":"唐","verses":["天津御柳碧遥遥，轩骑相从半下朝。","行乐光辉寒食借，太平歌舞晚春饶。","红妆楼下东郊道，青草洲边南渡桥。","坐见司空扫西第，看君侍从落花朝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-3887366a-5ca5-4e31-a43a-276ecef05990","tags":[]},{"id":"poem-b1b9b2670e40cbd4cf5057f2","title":"伤吴中","author":"李嘉祐","dynasty":"唐","verses":["馆娃宫中春已归，阖闾城头莺已飞。","复见花开人又老，横塘寂寂柳依依。","忆昔吴王在宫阙，馆娃满眼看花发。","舞袖朝欺陌上春，歌声夜怨江边月。","古来人事亦犹今，莫厌清觞与绿琴。","独向西山聊一笑，白云芳草自知心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-28a07ece-270c-4194-ad97-8b944d5d4293","tags":[]},{"id":"poem-b1bb3abcfb89da0d3eb70298","title":"鼓吹曲辞 凯歌六首 三","author":"岑参","dynasty":"唐","verses":["鸣笳擂鼓拥回军，破国平蕃昔未闻。","大夫鹊印摇边月，天将龙旗掣海云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fd06ba1d-9d8e-4b20-884b-bcf4c93507a6","tags":[]},{"id":"poem-b1bfe19b1b5e4ebb45518182","title":"更漏子·春夜阑","author":"牛峤","dynasty":"五代","verses":["春夜阑，更漏促，金烬暗挑残烛。","惊梦断，锦屏深，两乡明月心。","闺草碧，望归客，还是不知消息。","辜负我，悔怜君，靠天天不闻。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-11","tags":[]},{"id":"poem-b1c0dc3f9279ffe851cda098","title":"燕燕","author":"佚名","dynasty":"先秦","verses":["燕燕于飞，差池其羽。之子于归，远送于野。瞻望弗及，泣涕如雨。","燕燕于飞，颉之颃之。之子于归，远于将之。瞻望弗及，伫立以泣。","燕燕于飞，下上其音。之子于归，远送于南。瞻望弗及，实劳我心。","仲氏任只，其心塞渊。终温且惠，淑慎其身。先君之思，以勖寡人。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-27","tags":[]},{"id":"poem-b1c1c7942f0f544a4059f8f4","title":"浣溪沙·越女淘金春水上","author":"薛昭蕴","dynasty":"五代","verses":["越女淘金春水上，步摇云鬓珮鸣珰，渚风江草又清香。","不为远山凝翠黛，只应含恨向斜阳，碧桃花谢忆刘郎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-33","tags":[]},{"id":"poem-b1dd068fa6daff907c435328","title":"木兰花·掩朱扉","author":"毛熙震","dynasty":"五代","verses":["掩朱扉，钩翠箔，满院莺声春寂寞。","匀粉泪，恨檀郎，一去不归花又落。","对斜晖，临小阁，前事岂堪重想着。","金带冷，画屏幽，宝帐慵熏兰麝薄。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-4","tags":[]},{"id":"poem-b1ddd60d44e46ba3991dd7fc","title":"蝶恋花·相见江南情不少","author":"毛滂","dynasty":"宋","verses":["相见江南情不少。","尔许多时，怪得无消耗。","淡日暖云句引到。","阑干寂寞怜春小。","宫面可忺匀画了。","粉瘦酥寒，一段天真好。","唤起玉儿娇睡觉。","半山残月南枝晓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-813","tags":[]},{"id":"poem-b1dde78d28a20d6c6062c3cc","title":"忆弟从善","author":"吕从庆","dynasty":"唐","verses":["弟贫居歙县，兄老住丰溪。","大被身分寝，长绳足共覊。","幅云横断岭，钩月照斜谿。","安得源源过，陶然乐黍鸡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c3385d36-1092-4360-a528-924e3da98e6c","tags":[]},{"id":"poem-b1e4eecc6da1a1e782d9b433","title":"兵火后野望  其一","author":"艾可翁","dynasty":"宋","verses":["干戈连万国，丘壑卧三年。","虎啸黄茅地，鸦屯白骨田。","渴虹疑竭海，腥雾欲沈天。","摇落前朝老，长怀鲁仲连。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-ad78ab14-5511-4a57-ab1e-19258c45bc92","tags":[]},{"id":"poem-b1e671f4e5c24dd693db3170","title":"晚秋 二","author":"佚名","dynasty":"唐","verses":["天涯地角一何长，雁塞龙塠万里疆。","每恨沦流经数载，更嗟缧绁泣千行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e7d67e74-af4a-41db-896a-bcc83bb7e01f","tags":[]},{"id":"poem-b1e70c94e9911da8807b0760","title":"金蕉叶","author":"无名氏《张协状元》","dynasty":"元","verses":["脱白挂绿，苦不肯共成眷属。","(后出接)蓦忽地思量，簌是奴没分福。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2622","tags":[]},{"id":"poem-b1eb0e0165f30e76426637af","title":"括浙江潮候","author":"释赞宁","dynasty":"宋","verses":["午未未未申，申卯卯辰辰。","巳巳巳午午，朔望一般轮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b8498238-27a7-4743-9212-67c2f19db29b","tags":[]},{"id":"poem-b205091094567ccfb9aa0209","title":"行露","author":"佚名","dynasty":"先秦","verses":["厌浥行露，岂不夙夜，谓行多露。","谁谓雀无角？何以穿我屋？谁谓女无家？何以速我狱？虽速我狱，室家不足！","谁谓鼠无牙？何以穿我墉？谁谓女无家？何以速我讼？虽速我讼，亦不女从！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-16","tags":[]},{"id":"poem-b208b7e93f726feb1fbc3b53","title":"次韵宣州使君陈中书见寄","author":"释居简","dynasty":"宋","verses":["听紫芝歌问绮园，橘中果有几何天。","试原雪夜玉堂梦，更了江春符竹缘。","新涨溢池荷叶小，煖风掠面柳花鲜。","大邦屏翰风骚地，应有诗人受一廛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-daf9d91a-a449-4bb4-918d-d435b0cca136","tags":[]},{"id":"poem-b20ab08e12225895609804ad","title":"喜迁莺·残蟾落","author":"薛昭蕴","dynasty":"五代","verses":["残蟾落，晓钟鸣，羽化觉身轻。","乍无春睡有余酲，杏苑雪初晴。","紫陌长，襟袖冷，不是人间风景。","回看尘土似前生，休羡谷中莺。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-34","tags":[]},{"id":"poem-b2139a95441304aa02b6818f","title":"咏史诗 田横墓","author":"胡曾","dynasty":"唐","verses":["古墓崔巍约路岐，歌传薤露到今时。","也知不去朝黄屋，祗为曾烹郦食其。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-db6b15f0-c322-4fe9-84a8-97f26a84c702","tags":[]},{"id":"poem-b2195eab3209e635c34f7584","title":"郊庙歌辞 享龙池乐章 第十章","author":"裴璀","dynasty":"唐","verses":["乾坤启圣吐龙泉，泉水年年胜一年。","始看鱼跃方成海，即覩龙飞利在天。","洲渚遥将银汉接，楼台直与紫微连。","休气荣光常不散，悬知此地是神仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b3f5fd27-c2a3-4007-9a52-21ac2aca7644","tags":[]},{"id":"poem-b21c513220c0aafafd47a923","title":"臧郎中挽歌二首  其一","author":"司马光","dynasty":"宋","verses":["积庆承前烈，呈才会圣时。","践杨朝有籍，治行吏为师。","僚友皆亲誉，黎民每去思。","惜哉违世早，志业未全施。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8928c1dc-b27b-4596-9745-b7e3ca15066a","tags":[]},{"id":"poem-b21c98e91faaf087c95167a5","title":"送杨法曹按括州","author":"孙逖","dynasty":"唐","verses":["东海天台山，南方缙云驿。","溪澄问人隐，岩险烦登陟。","潭壑随星使，轩车绕春色。","傥寻琪树人，为报长相忆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-45b5a565-7c75-4e92-8d2a-704146d86a85","tags":[]},{"id":"poem-b225ea8f89e22fcb7a8648f8","title":"赚煞尾","author":"杨景贤","dynasty":"元","verses":["填满起闷怀坑，担干起相思担。","我按不住风流俏胆，连理枝头谁了砍？对菱花接上瑶簪，过得南山！则少个包髻团衫。","俺爹便知道呵，也不妨，元定下的夫妻怎断？咱茶浓酒酣，趁着风轻云淡，省得着我倚门终日盼停骖。","(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4503","tags":[]},{"id":"poem-b22a0c71f5db422c6a7d0729","title":"题翠蛟亭","author":"李斗南","dynasty":"宋","verses":["壮士传观山石间，腰头宝剑祥光吐。","摩挲醉眼叱海神，嫌杀蛟龙作妖舞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-211d10fc-9109-403a-a317-abfa8b92eb5a","tags":[]},{"id":"poem-b22c7e71138b0b0b277fc8c1","title":"咏史诗 函谷关","author":"胡曾","dynasty":"唐","verses":["寂寂函关锁未开，田文车马出秦来。","朱门不养三千客，谁为鸡鸣得放回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-96465c8a-c13e-451a-bef6-3b0b06e93e7c","tags":[]},{"id":"poem-b22c9fcbbccfab70c13b51d2","title":"木兰花慢·倚危楼伫立","author":"柳永","dynasty":"宋","verses":["倚危楼伫立，乍萧索、晚晴初。","渐素景衰残，风砧韵响，双树红疏。","云衢。","见新雁过，奈佳人自别阻音书。","空遣悲秋念远，寸肠万恨萦纡。","皇都。","暗想欢游，成往事、动欷歔。","念对酒当歌，低帏并枕，翻恁轻孤。","归途。","纵凝望处，但斜阳暮霭满平芜。","赢得无言悄悄，凭阑尽日踟蹰。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-223","tags":[]},{"id":"poem-b22d34f2a3d1c9944f76d8b9","title":"十七","author":"王梵志","dynasty":"唐","verses":["四大乖和起，诸方请疗医。","（「请」，伯三五五八、伯三七一六、伯三六五六卷作「早」。","）长病煎汤药，求神觅好师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5cf8b360-b00d-43b2-a23c-5a99a71f3dc5","tags":[]},{"id":"poem-b22d61b42eda7fc4ccedf2f5","title":"和嵩阳客月夜忆上清人","author":"徐凝","dynasty":"唐","verses":["独夜嵩阳忆上仙，月明三十六峰前。","瑶池月胜嵩阳月，人在玉清眠不眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e7a0d35e-9aae-4ed8-b659-770eed8c0770","tags":[]},{"id":"poem-b22dcaa1f560622288d11271","title":"小诗并画卷奉送汾叟同年机宜奉议赴熙河幕府","author":"李公麟","dynasty":"宋","verses":["画出离筵已怆神，那堪真别渭城春。","渭城柳色休相恼，西出阳关有故人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9d33be31-afc6-4774-936b-2949925cbae2","tags":[]},{"id":"poem-b22fadc3b76c1c59d8fb1c91","title":"半阳湖","author":"朱存","dynasty":"唐","verses":["江南龙节水为乡，水不纯（《六朝事迹编类》作「绝」）阴又半阳。","一片湖光共深浅，两般泉脉异温凉。","（同前卷十八。","又见《六朝事迹编类》卷上。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6f796a5e-98d9-4dbf-b1ea-ea871d5d0303","tags":[]},{"id":"poem-b22fb9bcce5fd17f302503a5","title":"思山居一十首 清明后忆山中","author":"李德裕","dynasty":"唐","verses":["遥思寒食后，野老林下醉。","月照一山明，风吹百花气。","飞泉与万籁，髣髴疑箫吹。","不待曙华分，已应喧鸟至。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-30c05ba0-1740-48fc-9e3f-11936702d76d","tags":[]},{"id":"poem-b232186104cbd1fc221d089b","title":"芜城","author":"李端","dynasty":"唐","verses":["昔人登此地，丘陇已前悲。","今日又非昔，春风能几时。","风吹城上树，草没城边路。","城里月明时，精灵自来去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1187b7da-e4e4-4d63-800b-3e6e9d99d57e","tags":[]},{"id":"poem-b2351ac74b5e1c574c64937c","title":"咏史诗 谷口","author":"胡曾","dynasty":"唐","verses":["一旦天真逐水流，虎争龙战为诸侯。","子真独有烟霞趣，谷口耕锄到白头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4da65b32-330f-4063-8691-2d91beda9ed9","tags":[]},{"id":"poem-b23d269e1e470261ff5af0e5","title":"和孙秀才醉中二首  其二","author":"华镇","dynasty":"宋","verses":["吾邻有达士，时得问话言。","寄身杯酒间，万事不复论。","大嚼青精饭，高岸白纶巾。","愧非伯伦伴，辜此羲轩民。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-384b99df-76b2-4359-816d-90f6af838b2c","tags":[]},{"id":"poem-b246ca7d38c39050a6df8c7f","title":"喜迁莺·芳春景","author":"毛文锡","dynasty":"五代","verses":["芳春景，暖晴烟，乔木见莺迁。","传枝偎叶语关关，飞过绮丛间。","锦翼鲜，金毳软，百啭千娇相唤。","碧纱窗晓怕闻声，惊破鸳鸯暖。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-7","tags":[]},{"id":"poem-b24b10396383160c4f17cc6f","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["今后洁可奈守，算古往今来似奴稀有。","孩儿一去，到如今杳不回头。","十六年来音信杳莫有，父子同欢不念母。","休休，猛听得孤雁叫过南楼。","神思困倦，就在井栏边少睡片时则个。","(旦作睡介)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8983","tags":[]},{"id":"poem-b24cc057bd06bb04ec41bfea","title":"句","author":"李淮","dynasty":"唐","verses":["撩乱客心眠不得，秋庭一夜月中行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d63c5f81-bd14-4393-a5d9-13bf9464b9f2","tags":[]},{"id":"poem-b24d9a0b47cf37b87992102a","title":"临江仙·暮雨凄凄深院闭","author":"孙光宪","dynasty":"五代","verses":["暮雨凄凄深院闭，灯前凝坐初更。","玉钗低压鬓云横，半垂罗幕，相映烛光明。","终是有心投汉佩，低头但理秦筝。","燕双鸾耦不胜情，只愁明发，将逐楚云行。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-15","tags":[]},{"id":"poem-b255b7532026ed93d6457a2a","title":"渔家傲·几日轻阴寒测测","author":"周邦彦","dynasty":"宋","verses":["几日轻阴寒测测。","东风急处花成积。","醉踏阳春怀故国。","归未得。","黄鹂久住如相识。","赖有蛾眉能暖客。","长歌屡劝金杯侧。","歌罢月痕来照席。","贪欢适。","帘前重露成涓滴。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-378","tags":[]},{"id":"poem-b26242f5a6a95b6424450af4","title":"次韵翁士特相招居武夷","author":"李纲","dynasty":"宋","verses":["武夷山色翠崔嵬，应笑梁谿又到来。","脱网弱鳞初纵逸，伤弓倦翮尚惊猜。","闲中陶写资诗句，愁里销除赖酒杯。","谁道川途废光景，无根树子不妨栽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b676930a-0dbd-4ac4-8fc1-c51c6da23af9","tags":[]},{"id":"poem-b2648d20f1d6e12cef8ebf99","title":"嘉兴寒食","author":"徐凝","dynasty":"唐","verses":["嘉兴郭里逢寒食，落日家家拜扫回。","唯有县前苏小小，无人送与纸钱来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5c632e93-518e-46e1-af7c-3dadd656f33f","tags":[]},{"id":"poem-b26c7fb8ce6f9ebc408e673d","title":"句  其三","author":"林迥","dynasty":"宋","verses":["春晚花王在处稀，山中还信正芳菲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f38553a3-b0bd-4584-8b82-46dc88cbc52f","tags":[]},{"id":"poem-b26cabd7db5ce13a8301babe","title":"秋日疾中寄诸同志","author":"李咸用","dynasty":"唐","verses":["闲居无胜事，公干卧来心。","门静秋风晚，人稀古巷深。","花疎篱菊色，叶减井梧阴。","赖有斯文在，时时得强寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-56e0710a-ff8c-4707-ac10-97ff5ca0baca","tags":[]},{"id":"poem-b27dcdb93aebd5293a401838","title":"久留少城","author":"刘望之","dynasty":"宋","verses":["好去相羊乌角巾，却来躏踏软红尘。","酒因觅睡方成醉，金为收书更觉贫。","屡入草堂难下语，少留药市恐逢人。","可怜吊古凄凉意，只向扬家往返频。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-93bc0dde-7b0c-4788-a55a-fa93f0d8bb86","tags":[]},{"id":"poem-b28151b8ebaadda9d1c48f8d","title":"新楼诗二十首 海棠","author":"李绅","dynasty":"唐","verses":["海边佳树生奇彩，知是仙山取得栽。","琼蘂籍中闻阆苑，紫芝图上见蓬莱。","浅深芳萼通宵换，委积红英报晓开。","寄语春园百花道，莫争颜色泛金杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-09da42aa-01f7-4b8e-aa4f-7c243e4f1308","tags":[]},{"id":"poem-b2839df83dc4c118aed18621","title":"驻云飞","author":"徐田臣《杀狗记》","dynasty":"元","verses":["酒保无知，故意教他来笑耻。","堪恨乔才辈，恼得心儿碎。","呸！吃了这场亏，教人呕气。","吃得醺醺。","拚却今宵醉，痛饮前村踏雪山。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1759","tags":[]},{"id":"poem-b2897fc9f84bd5f1e95c17fe","title":"忆王孙·萋萋芳草忆王孙","author":"李重元","dynasty":"宋","verses":["萋萋芳草忆王孙。","柳外楼高空断魂。","杜宇声声不忍闻。","欲黄昏。","雨打梨花深闭门。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-110","tags":["宋词三百首"]},{"id":"poem-b290f84e73c56c66644baeb2","title":"蓦山溪·洗妆真态","author":"曹组","dynasty":"宋","verses":["洗妆真态，不作铅华御。","竹外一枝斜，想佳人、天寒日暮。","黄昏小院，无处著清香，风细细，雪垂垂，何况江头路。","月边疏影，梦到消魂处。","结子欲黄时，又须著、廉纤细雨。","孤芳一世，供断有情愁，销瘦却，东阳也，试问花知否。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-267","tags":["宋词三百首"]},{"id":"poem-b2913394934d2815925b96da","title":"蝶恋花·梦入江南烟水路","author":"晏几道","dynasty":"宋","verses":["梦入江南烟水路。","行尽江南，不与离人遇。","睡里消魂无说处。","觉来惆怅消魂误。","欲尽此情书尺素。","浮雁沈鱼，终了无凭据。","却倚缓弦歌别绪。","断肠移破秦筝柱。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-22","tags":["宋词三百首"]},{"id":"poem-b2979a747482930dfef078bc","title":"尾","author":"杨景贤","dynasty":"元","verses":["一念霎时生，万里须臾到。","四员将神通不小，抵多少万里西风鹤背高，离深山自上云霄。","自量度，则听得鬼哭神号，休猜做三唱阳关出霸桥。","(天王云)你离了通天大圣，怎不烦恼，倒欢喜为何？(金女唱)上圣道为甚不蹙青山懊恼，颠倒破朱颜含笑？大古里舍得这碧桃花下凤鸾交。","(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10309","tags":[]},{"id":"poem-b2984a3e889ffc3a1acbed50","title":"和张燕公耗磨日饮 二","author":"赵冬曦","dynasty":"唐","verses":["春来半月度，俗忌一朝闲。","不酌他乡酒，无堪对楚山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-816b98a8-2757-4645-b931-e2ee9ceffc9a","tags":[]},{"id":"poem-b29a13a2a43da6a462e0ffb3","title":"玉蝴蝶·望处雨收云断","author":"柳永","dynasty":"宋","verses":["望处雨收云断，凭阑悄悄，目送秋光。","晚景萧疏，堪动宋玉悲凉。","水风轻、苹花渐老，月露冷、梧叶飘黄。","遣情伤。","故人何在，烟水茫茫。","难忘。","文期酒会，几孤风月，屡变星霜。","海阔山遥，未知何处是潇湘。","念双燕、难凭远信，指暮天、空识归航。","黯相望。","断鸿声里，立尽斜阳。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-150","tags":["宋词三百首"]},{"id":"poem-b29e5f3a4dc33ff2d10bad50","title":"道武夷冲祐观壁间读翁士特郎中留题追怀感怆二首  其二","author":"李纲","dynasty":"宋","verses":["昔年曾约武夷孙，仙赏心违莫共论。","地下修文君已远，世间多难我犹存。","题诗屋壁事如昨，洒涕烟霞声为吞。","英爽故山应未冺，试凭楚些与招魂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-15983834-2e5a-4970-8bdd-84ef495f0f7f","tags":[]},{"id":"poem-b2a7e64958ec88b6fcd68105","title":"立春日宁州行营因赋朔风吹飞雪","author":"李益","dynasty":"唐","verses":["边声日夜合，朔风惊复来。","龙山不可望，千里一裴回。","捐扇破谁执，素纨轻欲裁。","非时妬桃李，自是舞阳台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-17e7a317-f30f-4f25-ac0f-d43111ce9da1","tags":[]},{"id":"poem-b2ab419c7a50c377ef31d79d","title":"送薛士昭  其二","author":"王十朋","dynasty":"宋","verses":["记得祥符识面时，回头二十二年非。","羡君学似川方至，顾我身如鸟倦飞。","老境天教重会合，异乡心最惜分违。","雁山亲旧如相问，征雁归时我亦归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b4e586c9-f2d2-4b13-b9fc-22141b422be8","tags":[]},{"id":"poem-b2ac1cd57eda41a376914066","title":"虎丘寺赠渔处士","author":"赵嘏","dynasty":"唐","verses":["兰若云深处，前年客重过。","岩空秋色动，水阔夕阳多。","早负江湖志，今如鬓发何。","唯思闲胜我，钓艇在烟波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b9191631-5a5a-40b4-b7fc-a24dc25e1fb5","tags":[]},{"id":"poem-b2b1116e5c0210813213101d","title":"踏莎行·秋入云山","author":"张抡","dynasty":"宋","verses":["秋入云山，物情潇洒。","百般景物堪图画。","丹枫万叶碧云边，黄花千点幽岩下。","已喜佳辰，更怜清夜。","一轮明月林梢挂。","松醪常与野人期，忘形共说清闲话。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-939","tags":[]},{"id":"poem-b2b627db89a98ba268a202a8","title":"信南山","author":"佚名","dynasty":"先秦","verses":["信彼南山，维禹甸之。畇畇原隰，曾孙田之。我疆我理，南东其亩。","上天同云。雨雪雰雰，益之以霡霂。既优既渥，既沾既足。生我百谷。","疆埸翼翼，黍稷彧彧。曾孙之穑，以为酒食。畀我尸宾，寿考万年。","中田有庐，疆埸有瓜。是剥是菹，献之皇祖。曾孙寿考，受天之祜。","祭以清酒，从以骍牡，享于祖考。执其鸾刀，以启其毛，取其血膋。","是烝是享，苾苾芬芬。祀事孔明，先祖是皇。报以介福。万寿无疆。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-209","tags":[]},{"id":"poem-b2b6b4c31216ce4d8a36f225","title":"游仙窟诗 赠崔十娘","author":"张文成","dynasty":"唐","verses":["今朝忽见渠姿首，不觉殷勤著心口。","令人频作许叮咛，渠家太剧难求守。","端坐剩心惊，愁来益不平。","看时未必相看死，难时那许太难生。","沈吟处幽室，相思转成疾。","自恨往还疎，谁肯交游密。","夜夜空知心失眼，朝朝无便投胶漆。","园里花开不避人，闺中面子翻羞出。","如今寸步阻天津，伊处留心更觅新。","莫言长有千金面，终归变作一抄尘。","生前有日但为乐，死后无春更著人。","祗可徜徉一生意，何须负持百年身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-96fdf055-b6c6-4ab1-800e-7262c770af3f","tags":[]},{"id":"poem-b2ba9e7e45d66992f63c854d","title":"薄幸·青楼春晚","author":"吕渭老","dynasty":"宋","verses":["青楼春晚。","昼寂寂、梳匀又懒。","乍听得、鸦啼莺弄，惹起新愁无限。","记年时、偷掷春心，花间隔雾遥相见。","便角枕题诗，宝钗贳酒，共醉青苔深院。","怎忘得、回廊下，携手处、花明月满。","如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。","却谁拘管。","尽无言、闲品秦筝，泪满参差雁。","腰支渐小，心与杨花共远。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-116","tags":["宋词三百首"]},{"id":"poem-b2bf376f01cf76ed00103462","title":"长相思·山一程","author":"纳兰性德","dynasty":"清","verses":["山一程，水一程，身向榆关那畔行，夜深千帐灯。","风一更，雪一更，聒碎乡心梦不成，故园无此声。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-0","tags":[]},{"id":"poem-b2ca4d590481f8b827a17632","title":"柳十首 五","author":"李山甫","dynasty":"唐","verses":["弱带低垂可自由，傍他门户倚他楼。","金风不解相擡举，露压烟欺直到秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6106b1bf-bf97-4f80-956e-199203ab3384","tags":[]},{"id":"poem-b2d17ee0c3eda67d512ceefb","title":"番女怨·万枝香雪开已遍","author":"温庭筠","dynasty":"唐","verses":["万枝香雪开已遍，细雨双燕。","钿蝉筝，金雀扇，画梁相见。","雁门消息不归来，又飞回。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-11","tags":[]},{"id":"poem-b2d29be9ac9d092d675080d3","title":"精舍遇雨","author":"可止","dynasty":"唐","verses":["空门寂寂淡吾身，溪雨微微洗客尘。","卧向白云情未尽，任他黄鸟醉芳春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-5e32dfd5-c43d-4e56-8328-e102a0290bb8","tags":[]},{"id":"poem-b2d5c15db1c5d37152fdde87","title":"眼儿媚·酣酣日脚紫烟浮","author":"范成大","dynasty":"宋","verses":["酣酣日脚紫烟浮。","妍暖破轻裘。","困人天色，醉人花气，午梦扶头。","春慵恰似春塘水，一片縠纹愁。","溶溶泄泄，东风无力，欲皱还休。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-277","tags":["宋词三百首"]},{"id":"poem-b2e13feb5880443895d45945","title":"秋宿长安韦主簿厅","author":"李洞","dynasty":"唐","verses":["水木清凉夜直厅，愁人楼上唱寒更。","坐劳同步帘前月，鼠动床头印锁声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8b82a19f-8596-4c4f-b3f3-276667cfc0cb","tags":[]},{"id":"poem-b2e9ec42e35f0db766b7fe11","title":"失题","author":"李涉","dynasty":"唐","verses":["华表千年一鹤归，丹砂为顶雪为衣。","泠泠仙语人听尽，却向五云翻翅飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4e7b084a-3107-4f8a-9f3c-2d2cf8939700","tags":[]},{"id":"poem-b3002983004d8b72d6855d33","title":"临江仙·帘卷池心小阁虚","author":"李珣","dynasty":"五代","verses":["帘卷池心小阁虚，暂凉闲步徐徐。","芰荷经雨半凋疏，拂堤垂柳，蝉噪夕阳余。","不语低鬟幽思远，玉钗斜坠双鱼。","几回偷看寄来书，离情别恨，相隔欲何如。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-23","tags":[]},{"id":"poem-b3008f7222813c48ca326943","title":"句","author":"孟归唐","dynasty":"唐","verses":["练色有穷处，寒声无断（《江南野史》「断」作「尽」。","）时。","（《瀑布》。","见宋马令《南唐书》卷二十三《孟宾于传》。","亦见宋龙衮《江南野史》。","）（〖1〗《南唐书》：〖孟宾于〗初归江南，生子鳣归唐，亦能诗。","肄业庐山国学，尝得《瀑布诗》云：「练色有穷处，寒声无断时。","」隣房生亦得此联，遂交争之。","助教不能辩，讼于江州。","各以全篇意格定之，而归唐为胜。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-896c8677-c2c4-476a-b75e-405c1d708042","tags":["庐山"]},{"id":"poem-b31f2859da727d376be17ce8","title":"逢侠者","author":"钱起","dynasty":"唐","verses":["燕赵悲歌士，相逢剧孟家。","寸心言不尽，前路日将斜。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-逢俠者","tags":[]},{"id":"poem-b321b81fb4caaaa6438cf6be","title":"柳二首 二","author":"李绅","dynasty":"唐","verses":["千条垂柳拂金丝，日暖牵风叶学眉。","愁见花飞狂不定，还同轻薄五陵儿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-99056766-ad1b-45f2-9f00-454f16c68bdd","tags":[]},{"id":"poem-b3244473e68be983a5d23da5","title":"句","author":"陈素风","dynasty":"唐","verses":["三行故柳藏鸦树，一带长波灌竹泉。","千门竹影联春色，一段和光彻翠微。","西陵古木年年老，南陌风光日日新。","百宝镜轮金翡翠，五云丝网玉蜘蛛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1e3918d8-62ce-464b-a6c6-7995e6bdc915","tags":[]},{"id":"poem-b3268ba66012e2442f125e3e","title":"和邵尧夫秋霁登石阁","author":"司马光","dynasty":"宋","verses":["飞簷危槛出林端，王屋嵩丘咫尺间。","独爱高明游佛阁，岂知忧喜满尘寰。","目穷莽苍纤毫尽，身得逍遥万象闲。","暇日登临无厌数，悲风残叶已珊珊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-be337607-3a98-48df-8e8c-b38abba7b049","tags":[]},{"id":"poem-b32d1152c6c382b67e5c4212","title":"赠王侍御","author":"张籍","dynasty":"唐","verses":["心同野鹤与尘远，诗似冰壶见底清。","府县同趋昨日事，升沈不改故人情。","上阳春晚萧萧雨，洛水寒来夜夜声。","自叹独为折腰吏，可怜騘马路傍行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-daa86f6d-98fb-4231-84c3-f0cace4efbf6","tags":[]},{"id":"poem-b32e949aad12b8566b9e52b0","title":"万年欢·秋后花窠","author":"程大昌","dynasty":"宋","verses":["秋后花窠，放两枝三朵，来通芳信。","诗眼惊观，谓是春光倒运。","便即移尊就赏，更不惜、黄封赤印。","何期道，青女专时，露华忽变霜阵。","诗翁笑、但休问。","那阳和有脚，骎骎日进。","待得灰飞，梅畹果先骋俊。","次后连天红紫，向东风、万般娇韵。","恁时节，玉勒狨鞍，郊原莫论远近。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-246","tags":[]},{"id":"poem-b3306d969983e9c9b89cd07f","title":"同张少府和厍狄员外夏晚初霁南省寓直时兼充节度判官之作","author":"寇坦","dynasty":"唐","verses":["黄绶归休日，仙郎复奏余。","晏居当夏晚，寓直会晴初。","露散星文发，云披水镜虚。","高才推独唱，嘉会喜连茹。","月色摇春闼，香烟霭暝庐。","千门传夜警，万象照阶除。","少孺嘉能赋，文强阅赐书。","兼曹谋未展，入幕志方摅。","为奉灵台帛，恭先待漏车。","贞标不可仰，空此乐樵渔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-82ee3cd4-d4dd-4d26-96d8-c9bfcec45aa2","tags":[]},{"id":"poem-b33696de791a728021035237","title":"河满子·冠剑不随君去","author":"孙光宪","dynasty":"五代","verses":["冠剑不随君去，江河还共恩深。","歌袖半遮眉黛惨，泪珠旋滴衣襟。","惆怅云愁雨怨，断魂何处相寻。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-30","tags":[]},{"id":"poem-b33945566214828876961061","title":"临江仙·离别寻常今白首","author":"陈师道","dynasty":"宋","verses":["离别寻常今白首，更须竹雨萧萧。","不应都占世间豪。","清风居士手，杨柳洛城腰。","文字功名真自误，从今好月良宵。","只消怜取董娇饶。","修门君自到，不用我词招。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-317","tags":[]},{"id":"poem-b33c114ae122473a51571aef","title":"山居诗  其三○","author":"释延寿","dynasty":"宋","verses":["何如深谷一遗人，宴坐经行不累身。","废宅可嗟频换主，凋丛愁见几回春。","尖尖石笑烟笼碧，点点苔钱雨洗新。","堪笑古人非我意，居山多是避强秦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c0258a90-ecec-48f8-b803-09f9f8d1a269","tags":[]},{"id":"poem-b340c2b0948919b0450f8475","title":"颂古十九首  其一○","author":"释法全","dynasty":"宋","verses":["相逢把手上高峰，四顾寥寥天宇空。","一曲渔歌人不会，芦花飞起渡头风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-ecb218dc-2c50-4c04-bc25-828c2dc4e5d4","tags":[]},{"id":"poem-b3445ffc864551a350441655","title":"自蒲圻临湘趋岳阳道中作十首  其八","author":"李纲","dynasty":"宋","verses":["更欲投书吊汨罗，西风袅袅水增波。","江分梦泽於菟远，地近芳洲杜若多。","野鸟终年从萃止，木奴千树正婆娑。","卜居更作终焉计，华髪萧萧奈老何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b0a5b201-41ca-4e81-b99d-28ac69b1c11c","tags":[]},{"id":"poem-b351604a6ee732af89d4fb8b","title":"永遇乐·松菊堂深","author":"晁补之","dynasty":"宋","verses":["松菊堂深，芰荷池小，长夏清暑。","燕引雏还，鸠呼妇往，人静郊原趣。","麦天已过，薄衣轻扇，试起绕园徐步。","听衡宇、欣欣童稚，共说夜来初雨。","苍菅径里，紫葳枝上，数点幽花垂露。","东里催锄，西邻助晌，相戒清晨去。","斜川归兴，け然满目，回首帝乡何处。","只愁恐、轻鞭犯夜，灞陵旧路。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-131","tags":[]},{"id":"poem-b35401c72ea6953b8b2e3efc","title":"春日早朝","author":"张籍","dynasty":"唐","verses":["晓陌春寒朝骑来，瑞云深处见楼台。","夜来新雨沙堤湿，东上合门应未开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ce70861d-2ec3-4224-a989-c20b98b7c2c9","tags":[]},{"id":"poem-b35ddcecf3c64c62509c81f9","title":"玉楼春·春山敛黛低歌扇","author":"欧阳修","dynasty":"宋","verses":["春山敛黛低歌扇。","暂解吴钩登祖宴。","画楼钟动已魂销，何况马嘶芳草岸。","青门柳色随人远。","望欲断时肠已断。","洛城春色待君来，莫到落花飞似霰。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-668","tags":[]},{"id":"poem-b35f6882724052bb4c02b62d","title":"永丰桥闲坐","author":"吕从庆","dynasty":"唐","verses":["敝袜轻鞋缓足投，永丰桥上寄双眸。","山沿东舍环西舍，水遶南畴赴北畴。","村妇坐畦挑马齿，野童蹲涧采鸡头。","娱闲不觉忘中饭，一点斜阳射竹楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1606e976-6a04-42fe-bcb8-9cd8a26153a7","tags":[]},{"id":"poem-b3634bc9c000563a10bb7dc8","title":"途中旅思二首 一","author":"鲍溶","dynasty":"唐","verses":["喔喔鸡鸣晓，萧萧马辞枥。","草草名利区，居人少于客。","生期三万日，童耄半虚掷。","修短命半中，忧欢复相敌。","朝提黄金爵，暮造青松宅。","来往日相悲，北邙田土窄。","峨峨西天岳，锦绣明翠壁。","中有不死乡，千年无人迹。","心期周太子，下马拜虚碧。","鹤驾如可从，他年执烟策。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-79835f5d-98af-4613-a14b-f76ade22009e","tags":[]},{"id":"poem-b36f03037db10e2abb180f4c","title":"自商行谒复州卢使君虔","author":"孟郊","dynasty":"唐","verses":["一身遶千山，远作行路人。","未遂东吴归，暂出西京尘。","仲宣荆州客，今余竟陵宾。","往迹虽不同，托意皆有因。","商岭莓苔滑，石坂上下频。","江汉沙泥洁，永日光景新。","独泪起残夜，孤吟望初晨。","驱驰竟何事，章句依深仁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-15007e5d-15e8-4ebb-9dc3-e35af867b9a3","tags":[]},{"id":"poem-b375106ceb0d35855d906115","title":"宾之初筵","author":"佚名","dynasty":"先秦","verses":["宾之初筵，左右秩秩。笾豆有楚，殽核维旅。酒既和旨，饮酒孔偕。","钟鼓既设，举酬逸逸。大侯既抗，弓矢斯张。射夫既同，献尔发功。","发彼有的，以祈尔爵。","籥舞笙鼓，乐既和奏。烝衎烈祖，以洽百礼。百礼既至，有壬有林。","锡尔纯嘏，子孙其湛。其湛曰乐，各奏尔能。宾载手仇，室人入又。","酌彼康爵，以奏尔时。","宾之初筵，温温其恭。其未醉止，威仪反反。曰既醉止，威仪幡幡。","舍其坐迁，屡舞仙仙。其未醉止，威仪抑抑。曰既醉止，威仪抑抑。","是曰既醉，不知其秩。","宾既醉止，载号载呶。乱我笾豆，屡舞僛僛。是曰既醉，不知其邮。","侧弁之俄，屡舞傞傞。既醉而出，并受其福。醉而不出，是谓伐德。","饮酒孔嘉，维其令仪。","凡此饮酒，或醉或否。既立之监，或佐之史。彼醉不臧，不醉反耻。","式勿从谓，无俾大怠。匪言勿言，匪由勿语。由醉之言，俾出童羖。","三爵不识，矧敢多又。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-219","tags":[]},{"id":"poem-b386d2fc146eead97cb5e962","title":"闻夜啼赠刘正元","author":"孟郊","dynasty":"唐","verses":["寄泣须寄黄河泉，此中怨声流彻天。","愁人独有夜灯见，一纸乡书泪滴穿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0682ba7e-6308-42cc-87af-b17e138138cd","tags":["黄河"]},{"id":"poem-b3895cb2a3e25915d9d0f6ae","title":"蒸栗","author":"李纲","dynasty":"宋","verses":["风霜开栗皱，孕此頳虬卵。","嘉哉古所贽，饤饾入笾匴。","累累紫腰菱，烂烂火蚕茧。","甘腴能疗病，炎帝所编纂。","幽人夜读书，坐对铜檠短。","飕飕石鼎沸，焰焰地炉暖。","式将瓦甑炊，剖壳黄玉软。","乘饥进五六，腹已果然满。","吾尝位将相，日食万钱馔。","荒山啖芋栗，自胜太官脔。","乃知一饱余，万品徒过眼。","聊持荐杯酒，不假玻瓈盌。","忧慨不成眠，夜寒空展转。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-af7db047-6202-4612-a1d1-15e39509731f","tags":[]},{"id":"poem-b38b9bf5e15330c80e14dc92","title":"和陶渊明二十首  其一六","author":"陈造","dynasty":"宋","verses":["细阅史氏书，宛若身所经。","梦录以命之，过影纪亏成。","一尧间十秦，寒暑倏变更。","我起千岁后，游心于大庭。","俛仰海尘扬，鼓舞天籁鸣。","纷纷阅过前，表立俱志情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-42e9b3bb-5662-4158-a167-d262628cc87f","tags":[]},{"id":"poem-b38f97e939fe914db26acfa5","title":"茅山续志","author":"张颉","dynasty":"宋","verses":["步虚声起绕玄云，石乳烟销夜半分。","怪得瑶笙吹鹤过，碧坛夜醮玉宸君。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4d83600e-13c7-45b0-be2c-de46e11c0b52","tags":[]},{"id":"poem-b38fdf7d41edc8fffd33e109","title":"次韵梁广文重午吊古  其二","author":"陈造","dynasty":"宋","verses":["菰粽蘸蜜彩作丝，竹萌尚箨榴未子。","官居端午不可孤，小却文移谢胥史。","酒社切戒屐声疎，诗邮莫漫奚奴寄。","与君相望淮南北，宦游适偕乱山里。","老纡章绂我不称，路指云霄君未已。","相期玳席醉九室，先向花牋惊八米。","自昔词源浩千顷，粗许老子窥涯涘。","明朝酒罢诧里闾，颇尝见客今有此。","古人独醒怨不逢，时搴葹薋弃蘅芷。","吏隠顾窃诗酒乐，自公委蛇容食寐。","一欢况复酬佳节，豪饮当观建瓴水。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ecf246c6-0bed-46c0-b055-b90e03e7c5fa","tags":[]},{"id":"poem-b393574d11e9d4a5923e50b0","title":"答景亮二首  其一","author":"刘跂","dynasty":"宋","verses":["门无车马迹，卧榻两闲人。","野服风前薄，园蔬雨后新。","丝桐叔夜操，香火浄名真。","斜日穿簷入，悠悠对隙尘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-4e0258b3-f112-4ade-bdd2-4b323cd03458","tags":[]},{"id":"poem-b39d3ed3cd3fd54d3754f326","title":"繙书见舍弟去年自寿归郓道中诗怅然怀想久不作诗因集句为答用渭城体可歌也  其四","author":"刘跂","dynasty":"宋","verses":["荒山野水照斜晖，绿浄春深好染衣。","请君问取东流水，来岁如今归未归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-7991607f-1256-4b72-b33c-17268c0bc7f3","tags":[]},{"id":"poem-b39f5327d4db413934f1fd9b","title":"北海题渚宫","author":"窦俨","dynasty":"唐","verses":["纪南南望水城宽，水色天光混一般。","大抵江乡足诗景，咏吟如把画图看。","（见《舆地纪胜》卷六五《江陵府》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-453c1257-d259-4482-9eb8-2674e5f17b79","tags":[]},{"id":"poem-b39f9c12f01662bc0d15b514","title":"赏牡丹应教","author":"谦光","dynasty":"唐","verses":["拥衲对芳丛，由来事不同。","鬓从今日白，花似去年红。","艳异随朝露，馨香逐晓风。","何须对零落，然后始知空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-37fc7daa-d7c5-4df1-b273-24422a525b47","tags":[]},{"id":"poem-b3a69676e942282cab80db34","title":"宛陵寓居上沈大夫二首 二","author":"赵嘏","dynasty":"唐","verses":["溪树参差绿可攀，谢家云水满东山。","能忘天上他年贵，来结林中一日闲。","醉叩玉盘歌褭褭，暖鸣幽涧鸟关关。","觥筹不尽须归去，路在春风缥缈间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-56c3e46b-4df7-4303-86c8-37e7ffd3b9ad","tags":[]},{"id":"poem-b3aabe8887c6e3c953cf3e05","title":"偈颂七十一首  其二五","author":"释了惠","dynasty":"宋","verses":["面壁堆危引客过，问谁那更问如何。","道寻常已成多事，检点侬家事更多。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c8ce1013-80c2-4341-92c2-bcb114dd6ced","tags":[]},{"id":"poem-b3ae64993db09d8b8086317f","title":"寒食内宴二首 二","author":"张籍","dynasty":"唐","verses":["城阙沈沈向晓寒，恩当令节赐余欢。","瑞烟深处开三殿，春雨微时引百官。","宝树楼前分绣幕，彩花廊下暎华栏。","宫筵戏乐年年别，已得三廻对御看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2fc0e121-f66f-4368-9c8a-1fe8635e7ad1","tags":[]},{"id":"poem-b3aed70c35b5eebc42e766df","title":"宣甫以栟榈茶刷见惠继之以诗依韵奉和","author":"苏颂","dynasty":"宋","verses":["装橐分余具，茶筒使拂尘。","制时工匪易，得处赏尤频。","常与轮槽并，宜为焙匣珍。","斋中延客语，供办未应贫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-c0ff84fa-3831-4f24-b2e2-157a2bf740e2","tags":[]},{"id":"poem-b3b121e101184c820e55bf95","title":"唐大飨拜洛乐章 归和","author":"则天皇后","dynasty":"唐","verses":["言旋云洞兮蹑烟涂，永宁中宇兮安下都。","包涵动植兮顺荣枯，长贻宝贶兮赞璇图。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8d12c520-fd3c-4db1-ac44-f8475130ab63","tags":[]},{"id":"poem-b3b2b01fdbd48f552c6b81d5","title":"失调名·疏雨洗云轺","author":"仲殊","dynasty":"宋","verses":["疏雨洗云轺，望极银河影里。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-921","tags":[]},{"id":"poem-b3b7e037c0c53c987db219a0","title":"赠李宜之运干","author":"王十朋","dynasty":"宋","verses":["谪仙苗裔自非凡，家学端能嗣大参。","一见便知空冀北，三年长叹滞周南。","绝畦翰墨仆骚可，请试言词倚马堪。","莫道南来橐无宝，一编传得小云龛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-7aa72bd0-d90e-4170-9c65-807cf294ed83","tags":[]},{"id":"poem-b3ba89b495a1c91fd29233c1","title":"句","author":"罗衮","dynasty":"唐","verses":["此心不向常人说。","（《江湖小集》卷二十一李龏《剪绡集》引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5191f558-339e-4d52-b6e4-651659e8f22e","tags":[]},{"id":"poem-b3c0eee43917b65dab6797e1","title":"出车","author":"佚名","dynasty":"先秦","verses":["我出我车，于彼牧矣。自天子所，谓我来矣。召彼仆夫，谓之载矣。王事多难，维其棘矣。","我出我车，于彼郊矣。设此旐矣，建彼旄矣。彼旟旐斯，胡不旆旆？忧心悄悄，仆夫况瘁。","王命南仲，往城于方。出车彭彭，旗旐央央。天子命我，城彼朔方。赫赫南仲，𤞤狁于襄。","昔我往矣，黍稷方华。今我来思，雨雪载途。王事多难，不遑启居。岂不怀归？畏此简书。","喓喓草虫，趯趯阜螽。未见君子，忧心忡忡。既见君子，我心则降。赫赫南仲，薄伐西戎。","春日迟迟，卉木萋萋。仓庚喈喈，采蘩祁祁。执讯获丑，薄言还归。赫赫南仲，𤞤狁于夷。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-167","tags":[]},{"id":"poem-b3c4e4763e977d389f12efd2","title":"醉落魄・一斛珠·天低日暮","author":"李石","dynasty":"宋","verses":["天低日暮。","清商一曲行人住。","著人意态如飞絮。","才泊春衫，却被风吹去。","朝期暮约浑无据。","同心结尽千千缕。","今宵魂梦知何处。","翠竹芭蕉，又下黄昏雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-264","tags":[]},{"id":"poem-b3ca4dc8f64e78e815086c6e","title":"昔昔盐二十首 关山别荡子","author":"赵嘏","dynasty":"唐","verses":["那堪闻荡子，迢递涉关山。","肠为马嘶断，衣从泪滴斑。","愁看塞上路，讵惜镜中颜。","傥见征西雁，应传一字还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-666459a4-0a5a-4b67-a33b-b6c85e1ea9f6","tags":[]},{"id":"poem-b3e4277f05bca0fecce48b26","title":"登夏州城观送行人赋得六州胡儿歌","author":"李益","dynasty":"唐","verses":["六州胡儿六蕃语，十岁骑羊逐沙鼠。","沙头牧马孤雁飞，汉军游骑貂锦衣。","云中征戍三千里，今日征行何岁归。","无定河边数株柳，共送行人一杯酒。","胡儿起作和蕃歌，齐唱呜呜尽垂手。","心知旧国西州远，西向胡天望乡久。","回头忽作异方声，一声回尽征人首。","蕃音虏曲一难分，似说边情向塞云。","故国关山无限路，风沙满眼堪断魂。","不见天边青作冢，古来愁杀汉昭君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8879571b-91bc-47a4-b2f8-4094ed1440ed","tags":[]},{"id":"poem-b3e919da1d7a048fcd2ce662","title":"奉和九日幸临渭亭登高应制得直字","author":"李咸","dynasty":"唐","verses":["重阳乘令序，四野开晴色。","日月数初幷，乾坤圣登极。","菊黄迎酒泛，松翠凌霜直。","游海难为深，负山徒倦力。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-9cc7048a-1939-4de7-a928-a1e1986ed218","tags":[]},{"id":"poem-b3eb9b09f9339a117f99757a","title":"送张中正先生归庐陵","author":"苏颂","dynasty":"宋","verses":["白首师儒学愈专，未应褐博慕缨鲜。","离群旧友青云上，负笈诸生绛帐前。","京洛风尘销客袂，江湖春色趁归船。","飘然无复羁名累，道信乡闾足谓贤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ef1ba761-f08d-40f0-86ce-27e9b23af861","tags":[]},{"id":"poem-b3f137c5fba18b4808356a95","title":"生查子·四月到盘洲","author":"洪适","dynasty":"宋","verses":["四月到盘洲，长是黄梅雨。","屐齿满莓苔，避湿开新路。","极望绿阴成，不见乌飞处。","云采列奇峰，绝胜看庐阜。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-722","tags":[]},{"id":"poem-b3f3bc94855143bef2fa2a91","title":"赠昭应沈少府","author":"李洞","dynasty":"唐","verses":["行宫接县判云泉，袍色虽青骨且仙。","鄠杜忆过梨栗墅，潇湘曾棹雪霜天。","华山僧别留茶鼎，渭水人来锁钓船。","东送西迎终几考，新诗觅得两三联。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bbda892d-7948-48f7-8ffe-3e9414389a00","tags":[]},{"id":"poem-b3f98c1cd99416f8cbe8e3b0","title":"送裘父姪还乡二首  其一","author":"曾协","dynasty":"宋","verses":["气吐长虹一世豪，尚怜花草助风骚。","正须重碧浇胸次，不遣轻霜上鬓毛。","浪说清时敞东阁，谁捐好语到西曹。","江神却解归欤兴，賸放潮头百尺高。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-0ec0ec7d-f5f9-4b1a-9fad-daabade0f4a1","tags":[]},{"id":"poem-b4054f9ad593e800b7a49e3e","title":"横吹曲辞 出塞","author":"王之涣","dynasty":"唐","verses":["黄砂直上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春风不度玉门关。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-bcdf6f13-4cb9-418f-9279-c690522e0a27","tags":["山水","写景","唐诗三百首","乐府","思乡","边塞","将士"]},{"id":"poem-b40630456b097fb12fcb1ec0","title":"用看云体","author":"赵崇嶓","dynasty":"宋","verses":["上有悬石崖，下有滑石道。","中有观空人，容颜半枯槁。","坐息穷年岁，抱此希世宝。","虽然欠奇俊，尘翳已一扫。","或云大道初，不剩亦不少。","用力勤修为，苦辛坐中老。","新州有樵人，此意极了了。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f5aa5a1f-2a2c-4640-a320-4bbfb3e03618","tags":[]},{"id":"poem-b40abd09b9c32f754d9d9587","title":"寒食野望","author":"熊孺登","dynasty":"唐","verses":["拜扫无过骨肉亲，一年唯此两三辰。","冢头莫种有花树，春色不关泉下人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-86979e4a-c861-428f-b333-b4f4a82f4f6d","tags":[]},{"id":"poem-b40fb3774416604fd890b621","title":"春夜月","author":"徐铉","dynasty":"宋","verses":["幽人春望本多情，况是花繁月正明。","竟夕无言亦无寐，绕阶芳草影随行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5d330dc4-b9dd-458a-b465-6430de8f8433","tags":[]},{"id":"poem-b4180d57beaa8b8dcfc39b25","title":"钓竿篇","author":"沈佺期","dynasty":"唐","verses":["朝日敛红烟，垂竿向绿川。","人疑天上坐，鱼似镜中悬。","避檝时惊透，猜钩每误牵。","湍危不理辖，潭静欲留船。","钓玉君徒尚，征金我未贤。","为看芳饵下，贪得会无筌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-28c616fa-2fab-40c7-b4e1-eec241c762cc","tags":[]},{"id":"poem-b422380975d05ddcaeef11c6","title":"自咏十韵","author":"徐夤","dynasty":"唐","verses":["只合沧洲钓与耕，忽依萤烛愧功成。","未游宦路叨卑宦，才到名场得大名。","梁苑二年陪众客，温陵十载佐双旌。","钱财尽是侯王惠，骨肉偕承里巷荣。","拙赋偏闻镌印卖，恶诗亲见画图呈多栽桃李期春色，阔凿池塘许月明。","寒益轻裯饶美寝，出乘车马免徒行。","麤支菽粟防饥歉，薄有桮盘备送迎。","僧俗共邻栖隐乐，妻孥同爱水云清。","如今便死还甘分，莫更嫌他白发生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-cf228736-e4e4-4306-bfd1-e54a57d04b44","tags":[]},{"id":"poem-b42df4073be6c0f94b83f514","title":"宿江口","author":"于邺","dynasty":"唐","verses":["南渡人来绝，喧喧雁满沙。","自生江上月，长有客思家。","半夜下霜岸，北风吹荻花。","自惊归梦断，不得到天涯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-fa9fa888-1dfd-4b78-93e3-cd155dddf3e9","tags":[]},{"id":"poem-b42ea9579faa762eed9fdb24","title":"鼓钟","author":"佚名","dynasty":"先秦","verses":["鼓钟将将，淮水汤汤，忧心且伤。淑人君子，怀允不忘。","鼓钟喈喈，淮水湝湝，忧心且悲。淑人君子，其德不回。","鼓钟伐鼛，淮有三洲，忧心且妯。淑人君子，其德不犹。","鼓钟钦钦，鼓瑟鼓琴，笙磬同音。以雅以南，以龠不僭。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-207","tags":[]},{"id":"poem-b433c894f1a904470fd47c98","title":"浣溪沙·春暮黄莺下砌前","author":"毛熙震","dynasty":"五代","verses":["春暮黄莺下砌前，水晶帘影露珠悬，绮霞低映晚晴天。","弱柳万条垂翠带，残红落地碎香钿，蕙风飘荡散轻烟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-33","tags":[]},{"id":"poem-b444e09fdd413a32fdbead79","title":"横吹曲辞 出塞","author":"马戴","dynasty":"唐","verses":["金带连环束战袍，马头冲雪度临洮。","卷旗夜劫单于帐，乱斫胡兵缺宝刀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b2898783-b22c-4ded-b6c0-492b879a3b2d","tags":["战争","边塞"]},{"id":"poem-b44aeb2fcaa283e958592c4b","title":"佛国白赴召刘侍郎无言与诸贤作供于报恩题壁以纪傍有隆茂宗所作古木怪石","author":"释居简","dynasty":"宋","verses":["白也度苕谿，诸贤重挽携。","金刀眷良集，铁画粲芳题。","神护藏书壁，鸿留印爪泥。","阿隆霜干老，附竝薄云霓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-7009cfc7-34ee-4990-85cc-2830d52e9ed8","tags":[]},{"id":"poem-b45fe24111485fe391f6b63d","title":"偈颂六十七首  其五二","author":"释原妙","dynasty":"宋","verses":["万法归一，一归何处。","狭路相逢，两手分付。","逴得便行，黄河三千年一度清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-81f638d9-ee7d-4b7e-a325-bc60a3c5576d","tags":[]},{"id":"poem-b469959b4f33d0d20b2219c4","title":"眼儿媚·咏梅","author":"纳兰性德","dynasty":"清","verses":["莫把琼花比澹妆，谁似白霓裳。","别样清幽，自然标格，莫近东墙。","冰肌玉骨天分付，兼付与凄凉。","可怜遥夜，冷烟和月，疏影横窗。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-35","tags":[]},{"id":"poem-b46cf9c99b953ca4c32e45c5","title":"光穆皇后挽歌三首  其三","author":"徐铉","dynasty":"宋","verses":["隠隠阊门路，烟云晓更愁。","空瞻金辂出，非是濯龙游。","德感人伦正，风行内职修。","还随偶物化，同此畏轩丘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-73dd5bba-3cfe-48cf-b2d5-079f4061264c","tags":[]},{"id":"poem-b4858c6251f43d6fc10ae728","title":"再次敬字韵","author":"陈造","dynasty":"宋","verses":["阴风摧行车，欻作三日病。","使君敬爱客，重此折简请。","碧香骈柔嘉，虚辱礼意盛。","老衰已不支，节候况失正。","寒事动奸时，暖气久未应。","积雨迁厥怒，密雪佐其劲。","新诗挽春色，堕我桃李径。","飘萧寻芳兴，亟问果下乘。","把君珠两两，后照仍前映。","重烧见火浣，百炼乃宝镜。","折箠敌可笞，歌风楚不竞。","读檄且观涛，寿我无有命。","旧闻句通神，疟鬼褫魄听。","援君起废手，直用古贤订。","笑送梦中竖，子行良机警。","亦笑齐东翁，口舌邀客敬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-3a9158ae-4618-45c3-b04c-914d55ba14f2","tags":[]},{"id":"poem-b489cc62164c432e14929e83","title":"白牡丹","author":"裴士淹","dynasty":"唐","verses":["长安年少惜春残，争认慈恩紫牡丹。","别有玉盘乘露冷，无人起就月中看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5ba0b4c0-83ef-4b26-a295-dbd2d216573c","tags":["咏物","咏物诗","牡丹","花","赞美","写花"]},{"id":"poem-b4a883d53f1769beab4d8a10","title":"幸秦始皇陵","author":"中宗皇帝","dynasty":"唐","verses":["眷言君失德，骊邑想秦余。","政烦方改篆，愚俗乃焚书。","阿房久已灭，阁道遂成墟。","欲厌东南气，翻伤掩鲍车。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-651e8254-c709-49e8-86fd-0153306ff555","tags":[]},{"id":"poem-b4b35ae60f0861ba6405c3c3","title":"唐享昊天乐 第四","author":"则天皇后","dynasty":"唐","verses":["巍巍叡业广，赫赫圣基隆。","菲德承先顾，祯符萃眇躬。","铭开武岩侧，图荐洛川中。","微诚讵幽感，景命忽昭融。","有怀慙紫极，无以谢玄穹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fab579bd-1352-4182-94b7-884e42c83bc4","tags":[]},{"id":"poem-b4bf13859b2de14d9d1f7ee3","title":"淇上酬薛三据兼寄郭少府微","author":"高适","dynasty":"唐","verses":["自从别京华，我心乃萧索。","十年守章句，万事空寥落。","北上登蓟门，茫茫见沙漠。","倚劒对风尘，慨然思卫霍。","拂衣去燕赵，驱马怅不乐。","天长沧洲路，日暮邯郸郭。","酒肆或淹留，渔潭屡栖泊。","独行备艰险，所见穷善恶。","永愿拯刍荛，孰云干鼎镬。","皇情念淳古，时俗何浮薄。","理道资任贤，安人在求瘼。","故交负灵奇，逸气抱謇谔。","隐轸经济具，纵横建安作。","才望忽先鸣，风期无宿诺。","飘飖劳州县，迢递限言谑。","东驰眇贝丘，西顾弥虢略。","淇水徒自流，浮云不堪托。","吾谋适可用，天路岂寥廓。","不然买山田，一身与耕凿。","且欲同鹪鹩，焉能志鸿鹄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-13619ace-57d2-4444-ac03-15481045fff6","tags":[]},{"id":"poem-b4c29e9de4eeae3175a1053f","title":"民夫","author":"宋伯仁","dynasty":"宋","verses":["阃帅差夫欲太平，浚河才了又修城。","挑泥鍫镢无休日，失业妻儿有叹声。","两个布衫寒透骨，半盂蒸饭冷无羹。","何时一统山河了，只向春田带雨耕。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-cd42db57-46a8-4d33-8adc-020b37b51ffe","tags":[]},{"id":"poem-b4c459d315113106ac24806c","title":"主人故池","author":"王建","dynasty":"唐","verses":["高池高阁上连起，荷叶团团盖秋水。","主人已远凉风生，旧客不来芙蓉死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9e4bef3c-d99d-41e4-899c-c0110ff6e378","tags":[]},{"id":"poem-b4cac581c4261caf444b00d3","title":"敬寄族弟唐十八使君","author":"杜甫","dynasty":"唐","verses":["与君陶唐后，盛族多其人。","圣贤冠史籍，枝派罗源津。","在今气磊落，巧伪莫敢亲。","介立实吾弟，济时肯杀身。","物白讳受玷，行高无污真。","得罪永泰末，放之五溪滨。","鸾凤有铩翮，先儒曾抱麟。","雷霆霹长松，骨大却生筋。","一失不足伤，念子孰自珍。","泊舟楚宫岸，恋阙浩酸辛。","除名配清江，厥土巫峡邻。","登陆将首途，笔札枉所申。","归朝跼病肺，叙旧思重陈。","春风洪涛壮，谷转颇弥旬。","我能泛中流，搪突鼍獭瞋。","长年已省柁，慰此贞良臣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-47efe0be-f2da-4171-9d3b-abd166ae86f9","tags":[]},{"id":"poem-b4d01cf17c82ecd4aedccf88","title":"寄路温州","author":"皎然","dynasty":"唐","verses":["欲问采灵药，如何学无生。","爱鹤颇似君，且非求仙情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-eaeabc88-36d3-4e27-a3ac-9f63a4120216","tags":[]},{"id":"poem-b4d056eaccf3d43a033db8c9","title":"醉中天","author":"杨景贤","dynasty":"元","verses":["文殊智慧施檀信，普贤行法济凡人。","(唐僧云)伽叶、阿难如何？(贫波唱)伽叶、阿难守着世尊，向佛会高参论。","(唐僧云)此间到雷音寺，多少路程？(贫婆唱)你听那磬韵钟声远闻，兀的鹿野苑雷音近。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3386","tags":[]},{"id":"poem-b4d850ceb9acfbdfffb3675b","title":"驾幸新丰温泉宫献诗三首 二","author":"上官昭容","dynasty":"唐","verses":["鸾旗掣曳拂空回，羽骑骖驔蹑景来。","隐隐骊山云外耸，迢迢御帐日边开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-47e4501e-c5e4-4074-90db-2cd50aeaf708","tags":[]},{"id":"poem-b4eb07eea15294a0525f676d","title":"野次喜雪","author":"明皇帝","dynasty":"唐","verses":["拂曙辟行宫，寒皋野望通。","繁云低远岫，飞雪舞长空。","赋象恒依物，萦回屡逐风。","为知勤恤意，先此示年丰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1cdf7e65-ec12-41de-9474-7ff1eeacd5f3","tags":[]},{"id":"poem-b4f0b7d76e1553e2512cc632","title":"赋得路傍一株柳送邢校书赴延州使府","author":"李益","dynasty":"唐","verses":["路傍一株柳，此路向延州。","延州在何处，此路起悠悠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2571f14e-0c02-4fa0-a52c-f3b75069e0b6","tags":[]},{"id":"poem-b4f3f5f290884b8a74dd2b15","title":"在边亭赋得山花戏寄两领客使并滋三","author":"王孝廉","dynasty":"唐","verses":["芳树春色（疑应作花）色甚明，初开似笑听无声。","主人每日专攀尽，残片何时赠客情？","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7ad0f00d-7671-490e-84db-7cc49dd14a9a","tags":[]},{"id":"poem-b4f5387402d859f1bfd12be4","title":"客有言长沙军变向伯恭能弹治规画甚伟适得伯恭书亦道其事作韵语以寄之","author":"李纲","dynasty":"宋","verses":["长沙舞袖仅可旋，今作巨镇湖湘边。","骄兵夜探赤白丸，乘间窃发将啸翾。","不知向子有老拳，缚束健卒秖数言。","翩如鸟雀擒鹰鹯，奸腰凶领污龙泉。","弹压一境敢复喧，稚耋鼓舞喜欲颠。","归哺其饴甘晏眠，众服壮略称无前。","我归自南得之传，颇欣祖生先着鞭。","何不付与大将权，旍旗缤纷指云燕。","一鼓士气如突烟，黠虏破胆心少悛。","洒扫海内清戈鋋，使我衰病安庐田。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-cacfdf2d-d7f5-49e8-9f2d-fedc436f11ce","tags":[]},{"id":"poem-b50231a348cd003eb9dfc455","title":"南歌子·鬓堕低梳髻","author":"温庭筠","dynasty":"唐","verses":["鬓堕低梳髻，连娟细扫眉。","终日两相思，为君憔悴尽，百花时。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-39","tags":[]},{"id":"poem-b50675be21d7f2649e3ede8c","title":"将进酒","author":"李白","dynasty":"唐","verses":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金樽空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，君莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不愿醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣讙谑。","主人何为言少钱，径须沽取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e5e5f969-ddac-4491-9cfe-d77742e1416d","tags":["黄河","咏物","抒情","鼓吹曲辞","唐诗三百首","乐府","宴饮","哲理","水","咏物诗"]},{"id":"poem-b50b3708872022e845a2af12","title":"鹧鸪天·露下风前处处幽","author":"向子𬤇","dynasty":"宋","verses":["露下风前处处幽。","官黄如染翠如流。","谁将天上蟾宫树，散作人间水国秋。","香郁郁，思悠悠。","几年梦魂绕江头。","今朝得到芗林醉，白发相看万事休。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-103","tags":[]},{"id":"poem-b50dbbfd18d119fb8082623c","title":"题简上人西亭诗文后","author":"刘翼","dynasty":"宋","verses":["真如非字义，绮语道之疵。","未见西亭作，长为北磵欺。","晚因僧媚远，初实客从㬢。","多少才名士，沉沦世不知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-10f87e90-b4bb-46e7-9ef5-b0aece31acc5","tags":[]},{"id":"poem-b50de9eb74c3e8a864815529","title":"咏史诗 岘山","author":"胡曾","dynasty":"唐","verses":["晓日登临感晋臣，古碑零落岘山春。","松间残露频频滴，酷似当时堕泪人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-cb4c81d1-250f-4421-b195-8e83c20edf9b","tags":[]},{"id":"poem-b5161b2e2d925346334b94c8","title":"三换头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["名缰利锁，先自将人摧锉。","况鸾拘风束，甚日得到家？我也休怨他咱，这其间，只是我，不合来，长安看花。","闷杀我爹娘也，珠泪窄暗堕。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5055","tags":[]},{"id":"poem-b516211042943398fb889d60","title":"九叹·离世","author":"刘向","dynasty":"汉","verses":["灵怀其不吾知兮，灵怀其不吾闻。","就灵怀之皇祖兮，愬灵怀之鬼神。","灵怀曾不吾与兮，即听夫人之谀辞。","余辞上参于天坠兮，旁引之于四时。","指日月使延照兮，抚招摇以质正。","立师旷俾端辞兮，命咎繇使并听。","兆出名曰正则兮，卦发字曰灵均。","余幼既有此鸿节兮，长愈固而弥纯。","不从俗而诐行兮，直躬指而信志。","不枉绳以追曲兮，屈情素以从事。","端余行其如玉兮，述皇舆之踵迹。","群阿容以晦光兮，皇舆覆以幽辟。","舆中涂以回畔兮，驷马惊而横奔。","执组者不能制兮，必折轭而摧辕。","断镳衔以驰骛兮，暮去次而敢止。","路荡荡其无人兮，遂不御乎千里。","身衡陷而下沉兮，不可获而复登。","不顾身之卑贱兮，惜皇舆之不兴。","出国门而端指兮，冀壹寤而锡还。","哀仆夫之坎毒兮，屡离忧而逢患。","九年之中不吾反兮，思彭咸之水游。","惜师延之浮渚兮，赴汨罗之长流。","遵江曲之逶移兮，触石埼而衡游。","波澧澧而扬浇兮，顺长濑之浊流。","凌黄沱而下低兮，思还流而复反。","玄舆驰而并集兮，身容与而日远。","棹舟杭以横濿兮，济湘流而南极。","立江界而长吟兮，愁哀哀而累息。","情慌忽以忘归兮，神浮游以高历。","心蛩蛩而怀顾兮，魂眷眷而独逝。","叹曰：余思旧邦心依违兮，日暮黄昏羌幽悲兮，去郢东迁余谁慕兮，谗夫党旅其以兹故兮，河水淫淫情所愿兮，顾瞻郢路终不返兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-48","tags":[]},{"id":"poem-b51f62f61c166785bdd105f0","title":"喜见外弟又言别","author":"李益","dynasty":"唐","verses":["十年离乱后，长大一相逢。","问姓惊初见，称名忆旧容。","别来沧海事，语罢暮天钟。","明日巴陵道，秋山又几重。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d755f74b-18fd-44d1-a6e1-43e77490bb09","tags":["唐诗三百首","离别","五言律诗"]},{"id":"poem-b521b4bd09db1570a2032207","title":"十无诗寄桂府杨中丞 六","author":"赵嘏","dynasty":"唐","verses":["望断南云日已晡，便应凭梦过重湖。","不知自古登龙者，曾有因诗泥得无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9ba15920-f15e-4d0f-a239-6ac06fd075eb","tags":[]},{"id":"poem-b52c7850b17acedc7616b64c","title":"读东坡和渊明贫士诗寄诸子姪云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁谿诸弟以发数千里一笑  其六","author":"李纲","dynasty":"宋","verses":["自我去廊庙，远举如飞蓬。","徇道敢怀禄，谋身殊未工。","空余耿耿心，不惭楚两龚。","幸然诸季贤，意气与我同。","何当恩听归，兵息道路通。","却寻惠山路，杖策得相从。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-0c21e355-9b21-4884-b278-cdf2066f0a17","tags":[]},{"id":"poem-b530c95ee940879cb12d6cdf","title":"瑞鹤仙·绀烟迷雁迹","author":"蒋捷","dynasty":"宋","verses":["绀烟迷雁迹。","渐断鼓零钟，街喧初息。","风檠背寒壁。","放冰蜍飞到，丝丝窗隙。","琼瑰暗泣。","念乡关、霜芜似织。","漫将身、化鹤归来，忘却旧游端的。","欢极。","蓬壶蕖浸，花院梨溶，醉连春夕。","柯云罢弈。","樱桃在，梦难觅。","劝清光，乍可幽窗相伴，休照红楼夜笛。","怕人间、换谱伊凉，素娥未识。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-257","tags":["宋词三百首"]},{"id":"poem-b53a7573387bb3a0b9d95854","title":"小重山·春到长门春草青","author":"李清照","dynasty":"宋","verses":["春到长门春草青。","江梅些子破，未开匀。","碧云笼碾玉成尘。","留晓梦，惊破一瓯春。","花影压重门。","疏帘铺淡月，好黄昏。","二年三度负东君。","归来也，著意过今春。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-697","tags":[]},{"id":"poem-b53dc8e3ce2c625b05c9a2a9","title":"望岳","author":"杜甫","dynasty":"唐","verses":["岱宗夫如何，齐鲁青未了。","造化钟神秀，阴阳割昏晓。","荡胷生曾云，决眦入归鸟。","会当凌绝顶，一览众山小。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-12fdaad8-b197-4526-b56d-c7c713267248","tags":["唐诗三百首","泰山","五言古诗","励志","写景","初中古诗","山","哲理","八年级上册(课内)","写鸟","写山","描写山"]},{"id":"poem-b547e6c48cbc1dec9fd5caea","title":"回施先辈见寄新诗二首 一","author":"徐凝","dynasty":"唐","verses":["九幽仙子西山卷，读了绦绳系又开。","此卷玉清宫里少，曾寻真诰读诗来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4ef4711a-4f03-4edb-abbd-0ce9534db931","tags":[]},{"id":"poem-b552ea35366c64bafcfc6263","title":"丙申至前五日复坐南窗忆去年诗又成两章  其一","author":"张栻","dynasty":"宋","verses":["依然红日照窗楣，还是去年消息时。","妙理不须寻辙迹，只于生处验新知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-7e8a680d-fadd-4bfc-9f42-73703dd191b7","tags":[]},{"id":"poem-b55b4964368d94411d27192d","title":"新月二首  其一","author":"李纲","dynasty":"宋","verses":["碧落银蟾吐，知从何处来。","雕弓弦未上，宝镜匣初开。","照水钩沉影，窥人光满怀。","微升已西没，露坐兴悠哉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-61b33cb9-ac45-434c-a3a5-6027da3e89d7","tags":[]},{"id":"poem-b55d3a7ff322fb193242976f","title":"雨中花・夜行船·旆拂西风","author":"高观国","dynasty":"宋","verses":["旆拂西风，客应星汉，行参玉节征鞍。","缓带轻裘，争看盛世衣冠。","吟倦西湖风月，去看北塞关山，过离宫禾黍，故垒烟尘，有泪应弹。","文章俊伟，颖露囊锥，名动万里呼韩。","知素有、平戎手段，小试何难。","情寄吴梅香冷，梦随陇雁霜寒。","立勋未晚，归来依旧，酒社诗坛。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-417","tags":["西湖"]},{"id":"poem-b55ff8c2664a6a0cb24c38da","title":"谪岭南道中作","author":"李德裕","dynasty":"唐","verses":["岭水争分路转迷，桄榔椰叶暗蛮溪。","愁冲毒雾逢虵草，畏落沙虫避燕泥。","五月畬田收火米，三更津吏报潮鸡。","不堪肠断思乡处，红槿花中越鸟啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-190158b4-8500-4485-97c7-52d6a3cc7cc8","tags":["抒情","贬谪","写景"]},{"id":"poem-b560bfb533549aea56365655","title":"送圆仁三藏归本国","author":"栖白","dynasty":"唐","verses":["家山临晚日，海路信归桡。","树灭浑无岸，风生只有潮。","岁穷程未尽，天末国仍遥。","已入闽王梦，香花境外邀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6fd9c5e0-d17c-4f1b-96a3-f1d858f26bcd","tags":[]},{"id":"poem-b56d623cc3f7d53dfd8a1110","title":"鹊桥仙·红摧绿锉","author":"毛滂","dynasty":"宋","verses":["红摧绿锉，莺愁蝶怨，满院落花风紧。","醉乡好梦恰瞢腾，又冷落、一成吹醒。","柔红不耐，暗香犹好，觑著翻成不忍。","春心减尽眼长闲，更肯被、游丝牵引。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-839","tags":[]},{"id":"poem-b57c9787d2b2fa036792e26d","title":"柳枝词","author":"纳兰性德","dynasty":"清","verses":["池上闲房碧树围，帘纹如彀上斜晖。","生憎飞絮吹难定，一出红窗便不归。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-203","tags":[]},{"id":"poem-b582b51e0f99f451c85a2bec","title":"寄王侍御","author":"谭用之","dynasty":"宋","verses":["鸟尽弓藏良可哀，谁知归钓子陵台。","炼多不信黄金耗，吟苦须惊白发催。","喘月吴牛知夜至，嘶风胡马识秋来。","燕歌别后休惆怅，黍已成畦菊已开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c7593fea-f0e5-4ea6-b407-d4294e5ac25e","tags":[]},{"id":"poem-b583cab5c622b510ee3a8fb1","title":"和韦开州盛山十二首 上士泉缾","author":"张籍","dynasty":"唐","verses":["堦上一眼泉，四边青石甃。","唯有护净僧，添缾将盥漱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5209fed5-6f9b-4e12-9fd9-f2d91d154d90","tags":[]},{"id":"poem-b59876117e6c90a2d47baf73","title":"菩萨蛮·稽山鉴水无寒暑","author":"曹勋","dynasty":"宋","verses":["稽山鉴水无寒暑。","荷香莲露相倾注。","堂拟揖樵风。","山围晚照红。","桃根随秀叶。","玉麈频招客。","客况不言蓬。","回船逸兴同。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-192","tags":[]},{"id":"poem-b599bf980e3281b2bbf74d08","title":"次韵同经略舍人登七星山","author":"张维","dynasty":"宋","verses":["列岫凌虚滃翠岚，龙泓澄澈七星涵。","岩瞻好向西湖看，飞去何妨自岭南。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4ecea902-af88-4f3a-b073-a6c64ba893b9","tags":["西湖"]},{"id":"poem-b59f336d2c90b5b8c5534b81","title":"遣兴五首 二","author":"杜甫","dynasty":"唐","verses":["昔者庞德公，未曾入州府。","襄阳耆旧间，处士节独苦。","岂无济时策，终竟畏罗罟。","林茂鸟有归，水深鱼知聚。","举家依鹿门，刘表焉得取。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-914f158e-3c55-4db4-84bb-0f8a4b620f1d","tags":[]},{"id":"poem-b5a84288368d2358a36b5940","title":"客行","author":"唐求","dynasty":"唐","verses":["上山下山去，千里万里愁。","树色野桥暝，雨声孤馆秋。","南北眼前道，东西江畔舟。","世人重金玉，无金徒远游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ed0f4a06-37b2-4b14-9e6b-d06d6a0b9c5e","tags":[]},{"id":"poem-b5ae25c0ae80309589b113d3","title":"赠窦十九","author":"崔峒","dynasty":"唐","verses":["灵台暮宿意多违，木落花开羡客归。","江海几时传锦字，风尘不觉化缁衣。","山阳会里同人少，灞曲农时故老稀。","幸得汉皇容直谏，怜君未遇觉人非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b311196f-b1ae-4df5-8ee5-7e1af438478a","tags":[]},{"id":"poem-b5bf354880e214942ceade17","title":"书情献知己","author":"姚鹄","dynasty":"唐","verses":["日日恨何穷，巴云旧隐空。","一为栖寓客，二见北归鸿。","有道期攀桂，无门息转蓬。","赁居将罄比，乞食与僧同。","花月登临处，江山怅望中。","众皆轻病骥，谁肯救焦桐。","坐惜春还至，愁吟夜每终。","谷寒思变律，叶晚怯回风。","谒蔡慙王粲，怜衡冀孔融。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b6a05d15-81fa-4e16-a387-df81a786aa4c","tags":[]},{"id":"poem-b5c670b411c43af5beaaedad","title":"柏梯寺","author":"司马光","dynasty":"宋","verses":["凿石开蹊峻，登崖置阁危。","笑谈空谷应，步武白云随。","众壑如翻浪，邻州若布棋。","何当遂栖隐，身世两相遗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-96841a37-e4cf-4d0c-8fd6-28ebbbff7c53","tags":[]},{"id":"poem-b5c7256e154be7b31cce9c68","title":"偈颂六十七首  其六四","author":"释原妙","dynasty":"宋","verses":["急水滩头泊小舟，切须牢把遮绳头。","蓦然绳断难回避，直到通身血迸流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-74d43842-d520-46a9-9513-5eb6d4bc5dc2","tags":[]},{"id":"poem-b5c8685b5476c9b503ba5c6d","title":"江鸥","author":"崔道融","dynasty":"唐","verses":["白鸟波上栖，见人懒飞起。","为有求鱼心，不是恋江水。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b4ef7e39-4ece-44b8-825e-9ae1a179c90f","tags":[]},{"id":"poem-b5d27677f93e861525f32153","title":"郊庙歌辞 享先蚕乐章 昭庆","author":"不详","dynasty":"唐","verses":["仙坛礼既毕，神驾俨将升。","伫属深祥起，方期庶绩凝。","虔诚资宇内，务本勖黎蒸。","灵心昭备享，率土洽休征。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3df7186e-9419-4cd7-81b0-3f8eafda73e1","tags":[]},{"id":"poem-b5e63c6a69b3fbcad3dadbdd","title":"送严维归越州","author":"李嘉祐","dynasty":"唐","verses":["艰难只用武，归向淛河东。","松雪千山暮，林泉一水通。","乡心缘绿草，野思看青枫。","春日偏相忆，裁书寄剡中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6ddf2b76-d1de-4a26-adaa-48c0cd3203d2","tags":[]},{"id":"poem-b5edf3d3a3bbfd19a7a6fe86","title":"颂古三十一首  其七","author":"释安永","dynasty":"宋","verses":["石火光中验正邪，等闲拈却眼中沙。","自从不曾少盐酱，敢保渠侬未到家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c2584cef-452c-4c4f-9225-5be1acad73c8","tags":[]},{"id":"poem-b5ee1060f667d05fffa50ca8","title":"玉楼春·西湖南北烟波阔","author":"欧阳修","dynasty":"宋","verses":["西湖南北烟波阔。","风里丝簧声韵咽。","舞馀裙带绿双垂，酒入香腮红一抹。","杯深不觉琉璃滑。","贪看六么花十八。","明朝车马各西东，惆怅画桥风与月。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-675","tags":["西湖"]},{"id":"poem-b5f269ba392a5c38b6da09de","title":"送僧归日本","author":"钱起","dynasty":"唐","verses":["上国随缘住，来途若梦行。","浮天沧海远，去世法舟轻。","水月通禅观，鱼龙听梵声。","惟怜一灯影，万里眼中明。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-15274300-bd45-4898-ab14-9a3dead4b620","tags":["唐诗三百首","送别","五言律诗","惜别"]},{"id":"poem-b5f8201d7433a6dc40c4df79","title":"简兮","author":"佚名","dynasty":"先秦","verses":["简兮简兮，方将万舞。日之方中，在前上处。","硕人俣俣，公庭万舞。有力如虎，执辔如组。","左手执龠，右手秉翟。赫如渥赭，公言锡爵。","山有榛，隰有苓。云谁之思？西方美人。彼美人兮，西方之人兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-37","tags":[]},{"id":"poem-b5fe77805cb4f1e4f0873474","title":"潘丞孩子","author":"皎然","dynasty":"唐","verses":["爱子性情奇，初生玉树枝。","人曾天上见，名向月中知。","我识婴儿意，何须待佩觿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-620ec4d0-eaf2-420b-a6bd-6eff4dfa685e","tags":[]},{"id":"poem-b60362dcca4e01b3471b19ac","title":"普贤歌","author":"施惠《幽闺记》","dynasty":"元","verses":["(丑上)媒婆终日脚奔波，成就人间好事多。","这家也是我，那家也是我，也只为家贫没奈何。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3085","tags":[]},{"id":"poem-b606ea263166debc4c11c264","title":"春秋战国门 冯讙","author":"周昙","dynasty":"唐","verses":["兔窟穿成主再兴，辈流狐伏敢骄矜。","冯讙不是无能者，要试君心欲展能。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4d0328d2-9a89-40a5-bf72-987c5820211b","tags":[]},{"id":"poem-b6125bbafa85ce1c6e4c2a36","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小生)店名须号招商？(末)是。","这里是招商店。","(小生)少浼劳尊长。","(末)且说怎么祥个人，姓甚么？(小生)有个秀才身姓蒋。","(末)多少年纪了？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3042","tags":[]},{"id":"poem-b614f3b7d9ce4624acbcdac8","title":"又和开叔","author":"司马光","dynasty":"宋","verses":["寒梅犯雪荣，大隐久专名。","异种生江渚，何年到洛城。","色如虚室白，香似主人清。","响使吴儿见，不思菰菜羮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8c7657bb-4130-476d-a30e-aa340486e653","tags":[]},{"id":"poem-b6173476f61b339fa3b0be16","title":"早秋三首 一","author":"许浑","dynasty":"唐","verses":["遥夜泛清瑟，西风生翠萝。","残萤委玉露，早鴈拂银河。","高树晓还密，远山晴更多。","淮南一叶下，自觉老烟波。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-fedb06cc-37da-4aaf-8f39-85ebcb08b947","tags":["写景","秋天","唐诗三百首","五言律诗"]},{"id":"poem-b6241018f45650004b5cfca5","title":"赐房玄龄","author":"太宗皇帝","dynasty":"唐","verses":["太液仙舟迥，西园隐上才。","未晓征车度，鸡鸣关早开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-291dd1f7-f61e-42b0-bb46-a8b28f9a8ffd","tags":["赞颂","写人","写人诗"]},{"id":"poem-b62e52c155eca0bcc11bcf0d","title":"秋夜月","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["蒙见招，打扮十分俏，走到门前人都道，道奴奴脸上胭脂少，搽些又好，抹些又俏。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8064","tags":[]},{"id":"poem-b6390676538f628912e6bbab","title":"相思林","author":"徐凝","dynasty":"唐","verses":["游客远游新过岭，每逢芳树问芳名。","长林遍是相思树，争遣愁人独自行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1a72210d-7fe6-4ba8-86e8-a854668fb0a9","tags":[]},{"id":"poem-b645359e54d7376a859a4219","title":"叶西庐惠冬菊三绝  其一","author":"王柏","dynasty":"宋","verses":["风紧东篱长旧荄，主人杖屦日徘徊。","后时独立应无恨，少待梅花相伴开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-bcca5aa7-00eb-4df7-9cfc-d87a76aa4d02","tags":[]},{"id":"poem-b65744eaf3c244f7d5f8bc0d","title":"燕山亭·裁翦冰绡","author":"赵佶","dynasty":"宋","verses":["裁翦冰绡，打叠数重，冷淡燕脂匀注。","新样靓妆，艳溢香融，羞杀蕊珠宫女。","易得凋零，更多少、无情风雨。","愁苦。","闲院落凄凉，几番春暮。","凭寄离恨重重，这双燕，何曾会人言语。","天遥地远，万水千山，知他故宫何处。","怎不思量，除梦里、有时会去。","无据。","和梦也、有时不做。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-198","tags":["宋词三百首"]},{"id":"poem-b657b1f89f3520847974c01f","title":"无题二首 一","author":"李商隐","dynasty":"唐","verses":["昨夜星辰昨夜风，画楼西畔桂堂东。","身无彩凤双飞翼，心有灵犀一点通。","隔座送钩春酒暖，分曹射复蜡灯红。","嗟余听鼓应官去，走马兰台类断蓬。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3410e7ce-df3a-4ab8-bea3-7f681661b240","tags":["唐诗三百首","宴饮","七言律诗","爱情","相思","感慨","组诗"]},{"id":"poem-b65e295334ab4774b84f8340","title":"奉酬崔员外副使携琴宿使院见示","author":"李益","dynasty":"唐","verses":["忽闻此夜携琴宿，遂叹常时尘吏喧。","庭木已衰空月亮，城砧自急对霜繁。","犹持副节留军府，未荐高词直掖垣。","谁问南飞长绕树，官微同在谢公门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-13bfd558-12d2-49c1-8968-a94c7246c83a","tags":[]},{"id":"poem-b662c159bc3455b321142c62","title":"贺筵开","author":"无名氏《张协状元》","dynasty":"元","verses":["老夫年老脚衰，近日不出外，故不探知。","(旦)那更雨雪，纷纷恁作威，此处不曾得暂离。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2521","tags":[]},{"id":"poem-b66c3a0021b85f21d3425329","title":"生姜芽","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦上)闻知我小叔与儿夫，被龙卿、子传拖拽去公堂里，妄告他杀人罪。","奴家夜来不曾况详细，不知是狗穿人衣袂。","弄巧成拙是愚痴，怎知好意番成恶意！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1941","tags":[]},{"id":"poem-b67327231765c7f47f11e852","title":"品令·唱歌须是","author":"李","dynasty":"宋","verses":["唱歌须是，玉人檀口，皓齿冰肤。","意传心事，语娇声颤，字如贯珠。","老翁虽是解歌，无奈雪鬓霜须。","大家且道，是伊模样，怎如念奴。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-575","tags":[]},{"id":"poem-b6733db01175c0a7ae806453","title":"奉和圣制登骊山高顶寓目应制","author":"赵彦昭","dynasty":"唐","verses":["皇情遍九垓，御辇驻昭回。","路若随天转，人疑近日来。","河看大禹凿，山见巨灵开。","愿扈登封驾，常持荐寿杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c01af4a8-9d4a-4a41-a3d7-275eac4704a5","tags":[]},{"id":"poem-b67a12d5eeb0b6ba9ba4e8d1","title":"少年游·含羞倚醉不成歌","author":"张耒","dynasty":"宋","verses":["含羞倚醉不成歌。","纤手掩香罗。","偎花映烛，偷传深意，酒思入横波。","看朱成碧心迷乱，翻脉脉、敛双蛾。","相见时稀隔别多。","又春尽、奈愁何。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-351","tags":[]},{"id":"poem-b67ec8276d44b40564160dcd","title":"桃花夫人庙","author":"徐熙","dynasty":"唐","verses":["一树桃花发，桃花即是君。","空祠临野水，何处觅闲云。","事迹樵人说，炉香过客焚。","雨添碑上藓，难读古时文。","（见陆心源《宋诗纪事补遗》卷二引《续辑汉阳县志》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4b2b93b1-948f-45fa-96d2-51f3f0bc6374","tags":[]},{"id":"poem-b67fac08780d8cfecf297ba3","title":"曜日颂","author":"慧救","dynasty":"唐","verses":["见物明明绝见尘，闻声浩浩亦非因。","宗师真示无闻见，未晓徒劳见月新。","（《祖堂集》卷十一。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-66f848e0-016f-42b2-8f1c-5969864d287c","tags":[]},{"id":"poem-b6834a8ad8f36066b6fb191a","title":"浪淘沙·黄道雨初干","author":"谢懋","dynasty":"宋","verses":["黄道雨初干。","霁霭空蟠。","东风杨柳碧毵毵。","燕子不归花有恨，小院春寒。","倦客亦何堪。","尘满征衫。","明朝野水几重山。","归梦已随芳草绿，先到江南。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-304","tags":[]},{"id":"poem-b683934f04cfb75868ed08a9","title":"晚思","author":"司空曙","dynasty":"唐","verses":["蛩余窗下月，草湿堦前露。","晚景凄我衣，秋风入庭树。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-fe83cf62-7214-467e-ac9a-f776ab75a95b","tags":[]},{"id":"poem-b683d6ebd99d79917257d339","title":"依韵修睦上人山居十首 九","author":"李咸用","dynasty":"唐","verses":["太玄太易小窗明，古义寻来醉复醒。","西伯纵逢头已白，步兵如在眼应青。","寒猿断后云为槛，宿鸟惊时月满庭。","此景得闲闲去得，人间无事不曾经。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-aa7d5892-194f-45cf-936b-2f0134466487","tags":[]},{"id":"poem-b68b0679bfea0d2bfbaf871b","title":"送裴邕之上京","author":"皎然","dynasty":"唐","verses":["辞山偶世清，挟策忽西行。","帆过随江疾，衣沾楚雪轻。","尚文须献赋，重道莫论兵。","东观今多事，应高白马生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-efc703bb-6916-4269-bf9c-01513fd90d14","tags":[]},{"id":"poem-b68e20b6c551bd5283c7e42f","title":"净信院","author":"陈岩","dynasty":"宋","verses":["来自青松翠竹关，秋风吹帽醉醒间。","纷纷遮眼尘如海，拈起毫端又说山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-ebc670d4-80b9-4389-8122-9229bd8b68c7","tags":[]},{"id":"poem-b694be29e9058bed43f908fb","title":"女冠子·绿云高髻","author":"牛峤","dynasty":"五代","verses":["绿云高髻，点翠匀红时世。月如眉。","浅笑含双靥，低声唱小词。","眼看唯恐化，魂荡欲相随。","玉趾回娇步，约佳期。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-0","tags":[]},{"id":"poem-b69e023fc80e26659cf9b93f","title":"郊庙歌辞 朝日乐章 迎神","author":"不详","dynasty":"唐","verses":["太阳朝序，王宫有仪。","蟠桃彩驾，细柳光驰。","轩祥表合，汉历彰奇。","礼和乐备，神其降斯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c46d0f11-ff9a-402e-9306-cf79f7449187","tags":[]},{"id":"poem-b6b002bc961d28f5413aa108","title":"水调歌头·醉击玉壶缺","author":"蔡伸","dynasty":"宋","verses":["醉击玉壶缺，恨写绿琴哀。","悠悠往事谁问，离思渺难裁。","绿野堂前桃李，燕子楼中歌吹，那忍首重回。","唯有旧时月，远远逐人来。","小庭空，清夜永，独徘徊。","伴人幽怨，一枝潇洒陇头梅。","肠断云帆西去，目送烟波东注，千里接长淮。","为我将双泪，好过楚王台。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-917","tags":[]},{"id":"poem-b6b2705bb689880e77c2e7a8","title":"句  其五","author":"刘望之","dynasty":"宋","verses":["海山无瘴八蛮清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-32bcddea-75b8-4b07-bae5-5656a578adbf","tags":[]},{"id":"poem-b6b7f5a0d4f8766e31d531de","title":"忆昔二首 二","author":"杜甫","dynasty":"唐","verses":["忆昔开元全盛日，小邑犹藏万家室。","稻米流脂粟米白，公私苍廪俱丰实。","九州道路无豺虎，远行不劳吉日出。","齐纨鲁缟车班班，男耕女桑不相失。","宫中圣人奏云门，天下朋友皆胶漆。","百余年间未灾变，叔孙礼乐萧何律。","岂闻一绢直万钱，有田种谷今流血。","洛阳宫殿烧焚尽，宗庙新除狐兔穴。","伤心不忍问耆旧，复恐初从乱离说。","小臣鲁钝无所能，朝廷记识蒙禄秩。","周宣中兴望我皇，洒血江汉身衰疾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-80d0b9f1-7ae5-4b37-a34b-9e0d0e62e3fe","tags":[]},{"id":"poem-b6c0ca9e9277b57fcc2c9e2c","title":"题越台","author":"张洎","dynasty":"唐","verses":["我爱真人居，高台倚寥泬。","洞天开两扉，邈尔与世绝。","缥缈乘鸾女，华颜映绿发。","举手拂烟虹，吹笙弄松月，森萝窥万像，境异趣亦别。","何必服金丹，飞身向蓬阙。","（见《会稽掇英总集》卷十五。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-70f0754a-b507-4e26-afdd-8d7cfe3c9da2","tags":[]},{"id":"poem-b6cc698a08ad1720744719ab","title":"自叹","author":"宋伯仁","dynasty":"宋","verses":["又作淮南客，边尘压鬓毛。","夜长蛩聒聒，家远雁忉忉。","把酒天徒问，推篷月正高。","英雄四方志，休恋故人袍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-beb3abd1-3e7e-4651-93ef-01e283a6d7fb","tags":[]},{"id":"poem-b6d08a51f8939f93217678b6","title":"浣溪沙·古北口","author":"纳兰性德","dynasty":"清","verses":["杨柳千条送马蹄，北来征雁旧南飞。","客中谁与换春衣。","终古闲情归落照，一春幽梦逐游丝。","信回刚道别多时。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-97","tags":[]}];
